"""Authoring-only complete Function lowering policy, compiled into HIA continuations.

Runtime packages never execute or import this source. It preserves the exact608
Function and helper AST as the explicit policy input, rather than replay outputs.
"""

def _reject(message, code="E_HIA_PROGRAM_NATIVE"):
    raise HIAProgramNativeRejected(code + ": " + message)

def _words(typ):
    return 2 if typ in BYTE_RESOURCES else 1

def _bounds(typ):
    bits = WIDTHS[typ]
    return (-(1 << (bits - 1)), (1 << (bits - 1)) - 1) if typ.startswith("i") else (0, (1 << bits) - 1)

def _normalize(code, reg, typ):
    """Canonical full-register representation, including dirty incoming highs."""
    if typ == "unit":
        code.mov_imm(reg, 0)
    elif typ == "bool":
        code.alu_imm("and", reg, 1)
    elif typ in WIDTHS and WIDTHS[typ] < 64:
        count = 64 - WIDTHS[typ]
        code.shift_imm("shl", reg, count)
        code.shift_imm("sar" if typ.startswith("i") else "shr", reg, count)

def _prologue(code, frame):
    code.push("rbp")
    code.mov_rr("rbp", "rsp")
    # Touch each 4-KiB interval so a large frame cannot jump a stack guard.
    remaining = frame
    while remaining:
        amount = min(4096, remaining)
        code.alu_imm("sub", "rsp", amount)
        code.load("r11", "rsp", 0)
        remaining -= amount

class _Function:
    def __init__(self, parent, fn, index):
        self.parent, self.fn, self.index = parent, fn, index
        self.c = parent.c
        self.cursor = 8  # saved output-array pointer at rbp-8
        self.slots, self.types = {}, {}
        plan = parent.machine_plan or {}
        self.value_registers = plan.get("value_registers", {}).get(fn["name"], {})
        self.scalar_select = plan.get("instruction_selection", {}).get("scalar_select", "branch")
        self.blocks = {b["id"]: b for b in fn["blocks"]}
        for block in fn["blocks"]:
            definitions = block["params"] + [out for op in block["ops"] for out in op["out"]]
            for value in definitions:
                name, typ = value["name"], value["type"]
                self.slots[name] = self.allocate(_words(typ))
                self.types[name] = typ
        self.edge_words = max((sum(_words(p["type"]) for p in b["params"]) for b in fn["blocks"]), default=0)
        calls = [op for b in fn["blocks"] for op in b["ops"] if op["op"] == "call"]
        self.call_words = max((sum(_words(self.types[a]) for a in op["args"]) for op in calls), default=0)
        self.result_words = max((sum(_words(v["type"]) for v in op["out"]) for op in calls), default=0)
        self.edge_slot = self.allocate(max(1, self.edge_words))
        self.call_slot = self.allocate(max(1, self.call_words))
        self.result_slot = self.allocate(max(1, self.result_words))
        self.temporary = self.allocate(4)
        from .hia_machine_plan import VALUE_REGISTERS
        # Keep canonical staging/temporary locations disjoint from saved ABI
        # registers. A selected SSA value lives only in its checked register;
        # its canonical slot is reserved but no stale spill is ever read.
        self.saved_registers = {reg: self.allocate(1) for reg in VALUE_REGISTERS
                                if reg in self.value_registers.values()}
        # v4 r8/r9 values are caller-clobbered and are never saved here. The
        # independent plan checker restricts the entire function to its exact
        # leaf inventory (including exclusion of buffer.swap's implicit r8).
        self.frame = (self.cursor + 15) & -16
        if self.frame > MAX_FRAME_BYTES:
            _reject("function stack frame exceeds 64 KiB: " + fn["name"], "E_HIA_PROGRAM_LIMIT")
        self.trap = self.label("trap")

    def allocate(self, words):
        self.cursor += 8 * words
        return -self.cursor

    def label(self, suffix):
        return self.parent.label("fn" + str(self.index) + "_" + suffix)

    def block_label(self, name):
        return "fn" + str(self.index) + "_block_" + name

    def load(self, name, reg="rax", word=0):
        if name in self.value_registers:
            if word:
                _reject("multiword value cannot use the scalar register plan", "E_HIA_MACHINE_PLAN")
            self.c.mov_rr(reg, self.value_registers[name])
        else:
            self.c.load(reg, "rbp", self.slots[name] + word * 8)

    def store(self, name, reg="rax", word=0):
        if name in self.value_registers:
            if word:
                _reject("multiword value cannot use the scalar register plan", "E_HIA_MACHINE_PLAN")
            self.c.mov_rr(self.value_registers[name], reg)
        else:
            self.c.store("rbp", self.slots[name] + word * 8, reg)

    def immediate(self, name, value, word=0):
        self.c.mov_imm("rax", int(value) & ((1 << 64) - 1))
        self.store(name, word=word)

    def copy(self, source, destination):
        for i in range(_words(self.types[source])):
            self.load(source, word=i)
            self.store(destination, word=i)

    def fail_if(self, condition):
        self.c.jcc(condition, self.trap)

    def compare_imm(self, register, value):
        self.c.mov_imm("r11", value & ((1 << 64) - 1))
        self.c.cmp(register, "r11")

    def range_check(self, register, typ, source=None):
        source = typ if source is None else source
        lo, hi = _bounds(typ)
        before_lo, before_hi = _bounds(source)
        signed = source.startswith("i")
        if lo > before_lo:
            self.compare_imm(register, lo)
            self.fail_if("l" if signed else "b")
        if hi < before_hi:
            self.compare_imm(register, hi)
            self.fail_if("g" if signed else "a")

    def narrow_result(self, typ, checked=False):
        if checked and WIDTHS[typ] < 64:
            # Arithmetic used full-width canonical registers; enforce original width.
            self.range_check("rax", typ, "i64" if typ.startswith("i") else "u64")
        _normalize(self.c, "rax", typ)

    def condition_value(self, condition):
        self.c.setcc(condition, "rax")

    def edge(self, target, arguments):
        # All sources are staged first. Backedges may permute their own slots.
        n = 0
        for arg in arguments:
            for word in range(_words(self.types[arg])):
                self.load(arg, word=word)
                self.c.store("rbp", self.edge_slot + n * 8, "rax")
                n += 1
        n = 0
        for param in self.blocks[target]["params"]:
            for word in range(_words(param["type"])):
                self.c.load("rax", "rbp", self.edge_slot + n * 8)
                self.store(param["name"], word=word)
                n += 1
        self.c.jmp(self.block_label(target))

    def operation(self, ins):
        c = self.c
        op, args, attrs = ins["op"], ins["args"], ins["attrs"]
        out = [v["name"] for v in ins["out"]]
        typ = self.types[args[0]] if args else None
        if op == "const":
            self.immediate(out[0], 0 if attrs["value"] is None else attrs["value"])
        elif op.startswith("int.") and op.split(".")[1] in {"add", "sub", "mul"}:
            action, mode = op.split(".")[1:]
            checked = mode == "checked"
            self.load(args[0]); self.load(args[1], "rcx")
            if action == "mul":
                if checked and not typ.startswith("i"):
                    c.mul("rcx")
                    c.test("rdx", "rdx"); self.fail_if("ne")
                else:
                    c.imul_rr("rax", "rcx")
                    if checked:
                        self.fail_if("o")
            else:
                getattr(c, action)("rax", "rcx")
                if checked:
                    self.fail_if("o" if typ.startswith("i") else "b")
            self.narrow_result(typ, checked)
            self.store(out[0])
        elif op in {"int.div.checked", "int.rem.checked"}:
            self.load(args[0]); self.load(args[1], "rcx")
            c.test("rcx", "rcx"); self.fail_if("e")
            if typ.startswith("i"):
                safe = self.label("division")
                self.compare_imm("rax", _bounds(typ)[0]); c.jcc("ne", safe)
                self.compare_imm("rcx", -1); self.fail_if("e")
                c.label(safe); c.cqo(); c.idiv("rcx")
            else:
                c.xor("rdx", "rdx"); c.div("rcx")
            if op == "int.rem.checked":
                c.mov_rr("rax", "rdx")
            self.store(out[0])
        elif op in {"int.shl.checked", "int.shr.checked"}:
            self.load(args[0]); self.load(args[1], "rcx")
            self.compare_imm("rcx", WIDTHS[typ]); self.fail_if("ae")
            c.shift_cl("shl" if op == "int.shl.checked" else "sar" if typ.startswith("i") else "shr", "rax")
            self.narrow_result(typ); self.store(out[0])
        elif op == "int.neg.checked":
            self.load(args[0])
            if typ.startswith("i"):
                c.neg("rax"); self.fail_if("o")
                self.narrow_result(typ, True)
            else:
                c.test("rax", "rax"); self.fail_if("ne")
            self.store(out[0])
        elif op.startswith("bit."):
            self.load(args[0])
            action = op.split(".")[1]
            if action == "not":
                c.bitnot("rax")
            else:
                self.load(args[1], "rcx")
                getattr(c, {"and": "and_", "or": "or_", "xor": "xor"}[action])("rax", "rcx")
            self.narrow_result(typ); self.store(out[0])
        elif op.startswith("compare."):
            self.load(args[0]); self.load(args[1], "rcx"); c.cmp("rax", "rcx")
            predicates = ({"eq": "e", "ne": "ne", "lt": "l", "le": "le", "gt": "g", "ge": "ge"}
                          if typ.startswith("i") else
                          {"eq": "e", "ne": "ne", "lt": "b", "le": "be", "gt": "a", "ge": "ae"})
            self.condition_value(predicates[op.split(".")[1]]); self.store(out[0])
        elif op.startswith("bool."):
            self.load(args[0])
            if op == "bool.not":
                c.alu_imm("xor", "rax", 1)
            else:
                self.load(args[1], "rcx")
                getattr(c, "and_" if op == "bool.and" else "or_")("rax", "rcx")
            self.store(out[0])
        elif op == "int.cast":
            self.load(args[0]); dest = self.types[out[0]]
            if attrs["mode"] == "checked":
                self.range_check("rax", dest, typ)
            _normalize(c, "rax", dest); self.store(out[0])
        elif op == "select":
            if self.scalar_select == "cmov_scalar":
                # Core SELECT admits only already-defined nonresource values.
                # Register-only CMOV adds no conditional memory read or effect;
                # loading these scalar representations uses flag-preserving MOV.
                self.load(args[0]); c.test("rax", "rax")
                self.load(args[2]); self.load(args[1], "rcx")
                c.cmov("ne", "rax", "rcx"); self.store(out[0])
            else:
                yes, done = self.label("select_yes"), self.label("select_done")
                self.load(args[0]); c.test("rax", "rax"); c.jcc("ne", yes)
                self.copy(args[2], out[0]); c.jmp(done)
                c.label(yes); self.copy(args[1], out[0]); c.label(done)
        elif op == "call":
            n = 0
            for arg in args:
                for word in range(_words(self.types[arg])):
                    self.load(arg, word=word); c.store("rbp", self.call_slot + n * 8, "rax"); n += 1
            c.lea("rdi", "rbp", self.call_slot)
            c.lea("rsi", "rbp", self.result_slot)
            c.call(self.parent.function_symbol(attrs["function"]))
            n = 0
            for name in out:
                for word in range(_words(self.types[name])):
                    c.load("rax", "rbp", self.result_slot + n * 8); self.store(name, word=word); n += 1
        elif op in {"owner.move", "borrow.read", "borrow.mut"}:
            self.copy(args[0], out[0])
        elif op == "loan.end":
            pass  # Permission/lifetime transitions were independently verified.
        elif op in {"buffer.new", "buffer.try_new"}:
            self.allocate_buffer(args[0], out, op == "buffer.new")
        elif op == "buffer.len":
            self.load(args[0], word=1); self.store(out[0])
        elif op == "owner.drop":
            if typ == "chain":
                self.drop_chain(args[0])
            else:
                done = self.label("drop_done")
                self.load(args[0], "rdi"); c.test("rdi", "rdi"); c.jcc("e", done)
                c.call("free"); c.label(done)
        elif op in {"buffer.load", "buffer.store"}:
            self.load(args[0], "rdx", 1); self.load(args[1], "rcx")
            c.cmp("rcx", "rdx"); self.fail_if("ae")
            self.load(args[0]); c.add("rax", "rcx")
            if op == "buffer.load":
                c.load_u8("rax", "rax"); self.store(out[0])
            else:
                self.load(args[2], "rcx"); c.store_u8("rax", 0, "rcx")
        elif op == "buffer.swap":
            # Both checks precede either write, including equal-index operations.
            self.load(args[0], "rdx", 1)
            self.load(args[1], "rcx"); c.cmp("rcx", "rdx"); self.fail_if("ae")
            self.load(args[2], "r8"); c.cmp("r8", "rdx"); self.fail_if("ae")
            self.load(args[0], "rdi"); c.mov_rr("rsi", "rdi")
            c.add("rdi", "rcx"); c.add("rsi", "r8")
            c.load_u8("rax", "rdi"); c.load_u8("rcx", "rsi")
            c.store_u8("rdi", 0, "rcx"); c.store_u8("rsi", 0, "rax")
        elif op in {"buffer.fill", "buffer.copy", "buffer.move_within", "buffer.copy_range", "buffer.fill_range"}:
            self.bulk(op, args)
        elif op == "chain.empty":
            self.immediate(out[0], 0)
        elif op == "chain.is_empty":
            self.load(args[0]); c.test("rax", "rax"); self.condition_value("e"); self.store(out[0])
        elif op in {"chain.head_read", "chain.head_mut"}:
            self.load(args[0], "rdx"); c.test("rdx", "rdx"); self.fail_if("e")
            for word in range(2):
                c.load("rax", "rdx", word * 8); self.store(out[0], word=word)
        elif op == "chain.try_push":
            self.push_chain(args, out)
        elif op == "chain.pop":
            self.pop_chain(args[0], out)
        else:
            _reject("opcode lacks a direct machine lowering: " + op)

    def allocate_buffer(self, size, out, trapping):
        c = self.c
        empty, failed, done = self.label("alloc_empty"), self.label("alloc_failed"), self.label("alloc_done")
        self.load(size, "rsi")
        c.test("rsi", "rsi"); c.jcc("e", empty)
        self.compare_imm("rsi", (1 << 63) - 1); c.jcc("a", failed)
        c.mov_imm("rdi", 1); c.call("calloc")
        c.test("rax", "rax"); c.jcc("e", failed)
        self.store(out[0]); self.load(size); self.store(out[0], word=1)
        if not trapping:
            self.immediate(out[1], 1)
        c.jmp(done)
        c.label(empty)
        self.immediate(out[0], 0); self.immediate(out[0], 0, 1)
        if not trapping:
            self.immediate(out[1], 1)
        c.jmp(done)
        c.label(failed)
        if trapping:
            c.jmp(self.trap)
        else:
            self.immediate(out[0], 0); self.immediate(out[0], 0, 1); self.immediate(out[1], 0)
        c.label(done)

    def range_guard(self, buffer, offset, size):
        c = self.c
        self.load(buffer, "rax", 1)
        self.load(offset, "rcx"); c.cmp("rcx", "rax"); self.fail_if("a")
        c.sub("rax", "rcx")
        self.load(size, "rcx"); c.cmp("rcx", "rax"); self.fail_if("a")

    def bulk(self, op, args):
        c = self.c
        done = self.label("bulk_done")
        if op == "buffer.fill":
            self.load(args[0], "rdx", 1)
        elif op == "buffer.copy":
            self.load(args[2], "rdx")
            for owner in args[:2]:
                self.load(owner, "rax", 1); c.cmp("rdx", "rax"); self.fail_if("a")
        elif op == "buffer.fill_range":
            self.range_guard(args[0], args[1], args[2]); self.load(args[2], "rdx")
        elif op == "buffer.move_within":
            self.range_guard(args[0], args[1], args[3]); self.range_guard(args[0], args[2], args[3])
            self.load(args[3], "rdx")
        else:
            self.range_guard(args[0], args[2], args[4]); self.range_guard(args[1], args[3], args[4])
            self.load(args[4], "rdx")
        c.test("rdx", "rdx"); c.jcc("e", done)
        # Empty operations skip even derived pointer formation and libc calls.
        self.load(args[0], "rdi")
        if op in {"buffer.fill", "buffer.fill_range"}:
            if op == "buffer.fill_range":
                self.load(args[1], "rax"); c.add("rdi", "rax")
            self.load(args[1] if op == "buffer.fill" else args[3], "rsi")
            c.call("memset")
        else:
            self.load(args[0] if op == "buffer.move_within" else args[1], "rsi")
            if op in {"buffer.move_within", "buffer.copy_range"}:
                i = 1 if op == "buffer.move_within" else 2
                self.load(args[i], "rax"); c.add("rdi", "rax")
                self.load(args[i + 1], "rax"); c.add("rsi", "rax")
            c.call("memmove" if op == "buffer.move_within" else "memcpy")
        c.label(done)

    def push_chain(self, args, out):
        c = self.c
        failed, done = self.label("push_failed"), self.label("push_done")
        c.mov_imm("rdi", 24); c.call("malloc")
        c.test("rax", "rax"); c.jcc("e", failed)
        self.store(out[0]); c.mov_rr("rdx", "rax")
        self.load(args[1]); c.store("rdx", 0, "rax")
        self.load(args[1], word=1); c.store("rdx", 8, "rax")
        self.load(args[0]); c.store("rdx", 16, "rax")
        self.immediate(out[1], 0); self.immediate(out[1], 0, 1); self.immediate(out[2], 1)
        c.jmp(done)
        c.label(failed)
        self.copy(args[0], out[0]); self.copy(args[1], out[1]); self.immediate(out[2], 0)
        c.label(done)

    def pop_chain(self, arg, out):
        c = self.c
        empty, done = self.label("pop_empty"), self.label("pop_done")
        self.load(arg, "rdi"); c.test("rdi", "rdi"); c.jcc("e", empty)
        for word in range(2):
            c.load("rax", "rdi", word * 8); self.store(out[1], word=word)
        c.load("rax", "rdi", 16); self.store(out[0])
        c.call("free"); self.immediate(out[2], 1); c.jmp(done)
        c.label(empty)
        self.immediate(out[0], 0); self.immediate(out[1], 0); self.immediate(out[1], 0, 1); self.immediate(out[2], 0)
        c.label(done)

    def drop_chain(self, arg):
        c = self.c
        loop, node, done = self.label("chain_drop_loop"), self.label("chain_drop_node"), self.label("chain_drop_done")
        self.load(arg); c.store("rbp", self.temporary, "rax")
        c.label(loop)
        c.load("rdx", "rbp", self.temporary); c.test("rdx", "rdx"); c.jcc("e", done)
        c.load("rax", "rdx", 16); c.store("rbp", self.temporary + 8, "rax")
        c.load("rdi", "rdx", 0); c.test("rdi", "rdi"); c.jcc("e", node)
        c.call("free")
        c.label(node)
        c.load("rdi", "rbp", self.temporary); c.call("free")
        c.load("rax", "rbp", self.temporary + 8); c.store("rbp", self.temporary, "rax")
        c.jmp(loop); c.label(done)

    def render(self):
        c = self.c
        begin = len(c.data)
        _prologue(c, self.frame)
        for register, slot in self.saved_registers.items():
            c.store("rbp", slot, register)
        c.store("rbp", -8, "rsi")
        n = 0
        for param in self.fn["params"]:
            for word in range(_words(param["type"])):
                c.load("rax", "rdi", n * 8); self.store(param["name"], word=word); n += 1
        c.jmp(self.block_label(self.fn["entry"]))
        for block in self.parent.ordered_blocks(self.fn):
            c.label(self.block_label(block["id"]))
            for ins in block["ops"]:
                self.operation(ins)
            term = block["term"]
            if term["op"] == "jump":
                self.edge(term["target"], term["args"])
            elif term["op"] == "branch":
                other = self.label("branch_else")
                self.load(term["cond"]); c.test("rax", "rax"); c.jcc("e", other)
                self.edge(term["then"]["target"], term["then"]["args"])
                c.label(other); self.edge(term["else"]["target"], term["else"]["args"])
            elif term["op"] == "trap":
                c.jmp(self.trap)
            elif term["op"] == "ret":
                c.load("r10", "rbp", -8)
                n = 0
                for arg in term["values"]:
                    for word in range(_words(self.types[arg])):
                        self.load(arg, word=word); c.store("r10", n * 8, "rax"); n += 1
                for register, slot in self.saved_registers.items():
                    c.load(register, "rbp", slot)
                c.leave(); c.ret()
            else:
                _reject("unknown native terminator")
            if len(c.data) > MAX_TEXT_BYTES:
                _reject("direct code exceeds the 16 MiB text budget", "E_HIA_PROGRAM_LIMIT")
        c.label(self.trap); c.call("abort"); c.ud2()
        self.parent.symbols.append({"name": self.parent.function_symbol(self.fn["name"]),
                                    "offset": begin, "size": len(c.data) - begin, "global": False})
        self.parent.frames.append((self.fn["name"], self.frame))

def _native_globals():
    return {'WIDTHS': {'i8': 8, 'i16': 16, 'i32': 32, 'i64': 64, 'u8': 8, 'u16': 16, 'u32': 32, 'u64': 64, 'isize': 64, 'usize': 64}, 'BYTE_RESOURCES': frozenset({'buffer', 'readbuf', 'mutbuf'}), 'MAX_TEXT_BYTES': 16777216, 'MAX_FRAME_BYTES': 65536}

"""Finite authoring compiler for the complete, explicitly checked lowering policy.

This module is never imported by the runtime. Its instructions are control
blocks subsequently rendered as HIA; they are not precomputed lowering results.
Unsupported Python syntax fails generation instead of falling back to Python.
"""
from __future__ import annotations

import ast
from dataclasses import dataclass


OPS = {
    'GLOBAL': 1, 'ATTR': 2, 'SET_ATTR': 3, 'ITEM': 4, 'SET_ITEM': 5,
    'CALL': 6, 'PACK': 7, 'ITER': 8, 'NEXT': 9, 'TRUTH': 10,
    'BINARY': 11, 'UNARY': 12, 'COMPARE': 13, 'UNPACK': 14,
    'SLICE': 15, 'APPEND': 16, 'IMPORT': 17, 'RAISE': 18,
}
BINARY = {name: i for i, name in enumerate((
    'Add', 'Sub', 'Mult', 'FloorDiv', 'Div', 'Mod', 'Pow',
    'LShift', 'RShift', 'BitOr', 'BitXor', 'BitAnd'), 1)}
COMPARE = {name: i for i, name in enumerate((
    'Eq', 'NotEq', 'Lt', 'LtE', 'Gt', 'GtE', 'In', 'NotIn'), 1)}
UNARY = {'UAdd': 1, 'USub': 2, 'Invert': 3}
PACK = {'List': 1, 'Tuple': 2, 'Set': 3, 'Dict': 4}


@dataclass(frozen=True)
class Ref:
    kind: str
    index: int


@dataclass(frozen=True)
class Raw:
    value: int


class Literals:
    def __init__(self):
        self.values = []
        self.indices = {}
        for value in (None, False, True):
            self.get(value)

    def get(self, value):
        if type(value) not in (type(None), bool, int, str):
            raise ValueError('unsupported literal type: ' + type(value).__name__)
        if type(value) is int and not 0 <= value < 1 << 64:
            raise ValueError('integer literal must use explicit unary/arithmetic construction')
        key = (type(value), value)
        if key not in self.indices:
            self.indices[key] = len(self.values)
            self.values.append(value)
        return Ref('constant', self.indices[key])


class Function:
    def __init__(self, name, node, literals):
        self.name, self.node, self.literals = name, node, literals
        self.instructions = []
        self.locals = {}
        self.slot_count = 0
        self.labels = 0
        self.comp_scopes = []
        self.parameters = [a.arg for a in node.args.args]
        if node.args.posonlyargs or node.args.vararg or node.args.kwonlyargs or node.args.kwarg:
            raise ValueError('unsupported policy signature: ' + name)
        if len(self.parameters) > 4:
            raise ValueError('policy ABI accepts at most four bound arguments')
        for parameter in self.parameters:
            self.local(parameter)
        # Assignment establishes a Python local even before its first value.
        for value in ast.walk(node):
            if isinstance(value, ast.Name) and isinstance(value.ctx, ast.Store):
                self.local(value.id)
            elif isinstance(value, ast.ImportFrom):
                for alias in value.names:
                    self.local(alias.asname or alias.name)

    def temporary(self):
        result = Ref('slot', self.slot_count)
        self.slot_count += 1
        return result

    def local(self, name):
        if name not in self.locals:
            self.locals[name] = self.temporary()
        return self.locals[name]

    def variable(self, name):
        for scope in reversed(self.comp_scopes):
            if name in scope:
                return scope[name]
        return self.locals.get(name)

    def constant(self, value):
        return self.literals.get(value)

    def label(self):
        result = self.name + ':L' + str(self.labels)
        self.labels += 1
        return result

    def mark(self, label):
        self.instructions.append({'kind': 'mark', 'label': label})

    def move(self, destination, value):
        assert destination.kind == 'slot'
        self.instructions.append({'kind': 'move', 'destination': destination, 'value': value})

    def jump(self, label):
        self.instructions.append({'kind': 'jump', 'target': label})

    def effect(self, opcode, arguments, count=1, **extra):
        if len(arguments) > 8 or not 0 <= count <= 3:
            raise ValueError('foreign primitive exceeds the fixed HIA packet ABI')
        destinations = tuple(self.temporary() for _ in range(count))
        self.instructions.append({'kind': 'effect', 'opcode': OPS[opcode],
                                  'arguments': tuple(arguments), 'destinations': destinations, **extra})
        return destinations[0] if count == 1 else destinations

    def truth(self, value, yes, no):
        if value.kind == 'constant':
            literal = self.literals.values[value.index]
            # Literal truth is a static language operation, without foreign hooks.
            self.jump(yes if literal else no)
            return
        self.effect('TRUTH', (value,), count=0)
        self.instructions.append({'kind': 'flag', 'yes': yes, 'no': no})

    def condition(self, node, yes, no):
        if isinstance(node, ast.BoolOp):
            for value in node.values[:-1]:
                onward = self.label()
                self.condition(value, onward if isinstance(node.op, ast.And) else yes,
                               no if isinstance(node.op, ast.And) else onward)
                self.mark(onward)
            self.condition(node.values[-1], yes, no)
            return
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not):
            self.condition(node.operand, no, yes)
            return
        if isinstance(node, ast.Compare) and len(node.ops) > 1:
            left = self.expression(node.left)
            for index, (operator, comparator) in enumerate(zip(node.ops, node.comparators)):
                right = self.expression(comparator)
                result = self.compare(operator, left, right)
                onward = yes if index == len(node.ops) - 1 else self.label()
                self.truth(result, onward, no)
                if index != len(node.ops) - 1:
                    self.mark(onward)
                left = right
            return
        self.truth(self.expression(node), yes, no)

    def compare(self, operator, left, right):
        if isinstance(operator, (ast.Is, ast.IsNot)):
            result = self.temporary()
            self.instructions.append({'kind': 'identity', 'destination': result,
                'left': left, 'right': right, 'negate': isinstance(operator, ast.IsNot),
                'true': self.constant(True), 'false': self.constant(False)})
            return result
        return self.effect('COMPARE', (Raw(COMPARE[type(operator).__name__]), left, right))

    def expression(self, node):
        if isinstance(node, ast.Constant):
            return self.constant(node.value)
        if isinstance(node, ast.Name):
            local = self.variable(node.id)
            return local if local is not None else self.effect('GLOBAL', (self.constant(node.id),))
        if isinstance(node, ast.Attribute):
            return self.effect('ATTR', (self.expression(node.value), self.constant(node.attr)))
        if isinstance(node, ast.Subscript):
            value = self.expression(node.value)
            return self.effect('ITEM', (value, self.expression(node.slice)))
        if isinstance(node, ast.Slice):
            return self.effect('SLICE', tuple(self.expression(v) if v is not None else self.constant(None)
                                              for v in (node.lower, node.upper, node.step)))
        if isinstance(node, ast.BinOp):
            return self.effect('BINARY', (Raw(BINARY[type(node.op).__name__]),
                                          self.expression(node.left), self.expression(node.right)))
        if isinstance(node, ast.UnaryOp):
            if isinstance(node.op, ast.Not):
                result, yes, no, done = self.temporary(), self.label(), self.label(), self.label()
                self.condition(node.operand, no, yes)
                self.mark(yes); self.move(result, self.constant(True)); self.jump(done)
                self.mark(no); self.move(result, self.constant(False)); self.mark(done)
                return result
            return self.effect('UNARY', (Raw(UNARY[type(node.op).__name__]), self.expression(node.operand)))
        if isinstance(node, ast.BoolOp):
            result, done = self.temporary(), self.label()
            for index, value in enumerate(node.values):
                observed = self.expression(value); self.move(result, observed)
                if index != len(node.values) - 1:
                    onward = self.label()
                    self.truth(observed, onward if isinstance(node.op, ast.And) else done,
                               done if isinstance(node.op, ast.And) else onward)
                    self.mark(onward)
            self.mark(done)
            return result
        if isinstance(node, ast.IfExp):
            result, yes, no, done = self.temporary(), self.label(), self.label(), self.label()
            self.condition(node.test, yes, no)
            self.mark(yes); self.move(result, self.expression(node.body)); self.jump(done)
            self.mark(no); self.move(result, self.expression(node.orelse)); self.mark(done)
            return result
        if isinstance(node, ast.Compare):
            if len(node.ops) == 1:
                return self.compare(node.ops[0], self.expression(node.left), self.expression(node.comparators[0]))
            raise ValueError('value-context chained comparisons are outside this finite policy grammar')
        if isinstance(node, (ast.List, ast.Tuple, ast.Set, ast.Dict)):
            if isinstance(node, ast.Dict):
                if any(k is None for k in node.keys): raise ValueError('dict expansion is not admitted')
                values = tuple(v for pair in zip(node.keys, node.values) for v in pair)
            else:
                values = node.elts
            observed = tuple(self.expression(v) for v in values)
            return self.effect('PACK', (Raw(PACK[type(node).__name__]), Raw(len(observed))),
                               vector=observed)
        if isinstance(node, (ast.ListComp, ast.DictComp)):
            return self.comprehension(node)
        if isinstance(node, ast.Call):
            if (isinstance(node.func, ast.Name) and node.func.id in ('sum', 'max', 'any')
                    and len(node.args) == 1 and isinstance(node.args[0], ast.GeneratorExp)):
                return self.reduction(node)
            callee = self.expression(node.func)
            if any(isinstance(v, ast.Starred) for v in node.args) or len(node.args) > 4:
                raise ValueError('expanded or long call is outside the finite policy grammar')
            arguments = [self.expression(v) for v in node.args]
            if len(node.keywords) > 1 or any(v.arg is None for v in node.keywords):
                raise ValueError('expanded or multiple keyword call is outside the finite policy grammar')
            key, value = self.constant(None), self.constant(None)
            if node.keywords:
                key = self.constant(node.keywords[0].arg)
                value = self.expression(node.keywords[0].value)
            arguments += [self.constant(None)] * (4 - len(arguments))
            return self.effect('CALL', (callee, Raw(len(node.args)), *arguments, key, value))
        raise ValueError('unsupported policy expression: ' + ast.dump(node))

    def assign(self, target, value):
        if isinstance(target, ast.Name):
            local = self.variable(target.id)
            if local is None: local = self.local(target.id)
            self.move(local, value)
        elif isinstance(target, ast.Attribute):
            self.effect('SET_ATTR', (self.expression(target.value), self.constant(target.attr), value), count=0)
        elif isinstance(target, ast.Subscript):
            self.effect('SET_ITEM', (self.expression(target.value), self.expression(target.slice), value), count=0)
        elif isinstance(target, (ast.Tuple, ast.List)):
            if not 1 <= len(target.elts) <= 3: raise ValueError('unpack arity outside packet profile')
            pieces = self.effect('UNPACK', (value, Raw(len(target.elts))), count=len(target.elts))
            if len(target.elts) == 1: pieces = (pieces,)
            for child, piece in zip(target.elts, pieces): self.assign(child, piece)
        else:
            raise ValueError('unsupported assignment target: ' + ast.dump(target))

    def iterate(self, generators, body, *, first_iterator=None):
        if not generators:
            body(); return
        generator = generators[0]
        if generator.is_async: raise ValueError('async comprehension is not supported')
        iterator = first_iterator or self.effect('ITER', (self.expression(generator.iter),))
        head, found, done = self.label(), self.label(), self.label()
        self.mark(head); value = self.effect('NEXT', (iterator,))
        self.instructions.append({'kind': 'flag', 'yes': found, 'no': done})
        self.mark(found); self.assign(generator.target, value)
        for condition in generator.ifs:
            onward = self.label(); self.condition(condition, onward, head); self.mark(onward)
        self.iterate(generators[1:], body)
        self.jump(head); self.mark(done)

    def scope_for(self, generators):
        names = {v.id for g in generators for v in ast.walk(g.target)
                 if isinstance(v, ast.Name) and isinstance(v.ctx, ast.Store)}
        return {name: self.temporary() for name in sorted(names)}

    def comprehension(self, node):
        # The outer iterable is bound before the comprehension's own locals.
        first = self.effect('ITER', (self.expression(node.generators[0].iter),))
        result = self.effect('PACK', (Raw(PACK['Dict' if isinstance(node, ast.DictComp) else 'List']), Raw(0)), vector=())
        self.comp_scopes.append(self.scope_for(node.generators))
        def body():
            if isinstance(node, ast.DictComp):
                key, value = self.expression(node.key), self.expression(node.value)
                self.effect('SET_ITEM', (result, key, value), count=0)
            else:
                self.effect('APPEND', (result, self.expression(node.elt)), count=0)
        self.iterate(node.generators, body, first_iterator=first)
        self.comp_scopes.pop()
        return result

    def reduction(self, node):
        name, generator = node.func.id, node.args[0]
        if any(k.arg != 'default' for k in node.keywords) or len(node.keywords) > 1:
            raise ValueError('unsupported generator reduction keyword')
        if name != 'max' and node.keywords: raise ValueError('unexpected reduction keyword')
        if name == 'max' and not node.keywords:
            raise ValueError('the finite max-generator profile requires an explicit default')
        # These are explicit HIA loops; a hosted Python generator is never built.
        first = self.effect('ITER', (self.expression(generator.generators[0].iter),))
        result, seen, done = self.temporary(), self.temporary(), self.label()
        default = self.expression(node.keywords[0].value) if node.keywords else self.constant(False if name == 'any' else 0)
        self.move(result, default); self.move(seen, self.constant(False))
        self.comp_scopes.append(self.scope_for(generator.generators))
        def body():
            value = self.expression(generator.elt)
            if name == 'sum':
                self.move(result, self.effect('BINARY', (Raw(BINARY['Add']), result, value)))
            elif name == 'any':
                yes, no = self.label(), self.label()
                self.truth(value, yes, no); self.mark(yes)
                self.move(result, self.constant(True)); self.jump(done); self.mark(no)
            else:
                compare, take, onward = self.label(), self.label(), self.label()
                self.truth(seen, compare, take); self.mark(compare)
                self.truth(self.compare(ast.Gt(), value, result), take, onward)
                self.mark(take); self.move(result, value); self.move(seen, self.constant(True))
                self.mark(onward)
        self.iterate(generator.generators, body, first_iterator=first)
        self.comp_scopes.pop(); self.mark(done)
        return result

    def statements(self, nodes):
        for node in nodes:
            if isinstance(node, ast.Expr):
                if not isinstance(node.value, ast.Constant): self.expression(node.value)
            elif isinstance(node, ast.Assign):
                value = self.expression(node.value)
                for target in node.targets: self.assign(target, value)
            elif isinstance(node, ast.AugAssign):
                if isinstance(node.target, ast.Name):
                    old = self.variable(node.target.id); receiver = None
                elif isinstance(node.target, ast.Attribute):
                    receiver = self.expression(node.target.value)
                    old = self.effect('ATTR', (receiver, self.constant(node.target.attr)))
                else:
                    raise ValueError('unsupported augmented assignment target')
                value = self.effect('BINARY', (Raw(128 + BINARY[type(node.op).__name__]), old, self.expression(node.value)))
                if receiver is None: self.assign(node.target, value)
                else: self.effect('SET_ATTR', (receiver, self.constant(node.target.attr), value), count=0)
            elif isinstance(node, ast.If):
                yes, no, done = self.label(), self.label(), self.label()
                self.condition(node.test, yes, no); self.mark(yes)
                self.statements(node.body); self.jump(done); self.mark(no)
                self.statements(node.orelse); self.mark(done)
            elif isinstance(node, ast.For):
                iterator = self.effect('ITER', (self.expression(node.iter),))
                head, found, done = self.label(), self.label(), self.label()
                self.mark(head); value = self.effect('NEXT', (iterator,))
                self.instructions.append({'kind':'flag','yes':found,'no':done})
                self.mark(found); self.assign(node.target, value); self.statements(node.body)
                self.jump(head); self.mark(done); self.statements(node.orelse)
            elif isinstance(node, ast.While):
                head, body, done = self.label(), self.label(), self.label()
                self.mark(head); self.condition(node.test, body, done); self.mark(body)
                self.statements(node.body); self.jump(head); self.mark(done); self.statements(node.orelse)
            elif isinstance(node, ast.Return):
                self.instructions.append({'kind':'return','value':self.expression(node.value) if node.value is not None else self.constant(None)})
            elif isinstance(node, ast.ImportFrom):
                if node.level != 1 or node.module != 'hia_machine_plan' or len(node.names) != 1 or node.names[0].name != 'VALUE_REGISTERS':
                    raise ValueError('only the original explicit plan-register import is admitted')
                value = self.effect('IMPORT', ())
                self.move(self.local(node.names[0].asname or 'VALUE_REGISTERS'), value)
            elif isinstance(node, ast.Raise):
                if node.cause is not None or node.exc is None: raise ValueError('unsupported raise form')
                self.effect('RAISE', (self.expression(node.exc),), count=0)
            elif isinstance(node, ast.Pass):
                pass
            else:
                raise ValueError('unsupported policy statement: ' + ast.dump(node))

    def compile(self):
        self.statements(self.node.body)
        self.instructions.append({'kind':'return','value':self.constant(None)})
        return self


def compile_policy(source):
    tree = ast.parse(source)
    literals, functions = Literals(), []
    for node in tree.body:
        if isinstance(node, ast.FunctionDef):
            functions.append(Function(node.name, node, literals).compile())
        elif isinstance(node, ast.ClassDef) and node.name == '_Function':
            for method in node.body:
                if not isinstance(method, ast.FunctionDef): raise ValueError('unsupported Function class body')
                functions.append(Function('_Function.' + method.name, method, literals).compile())
        elif isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant) and type(node.value.value) is str:
            pass
        else:
            raise ValueError('policy contains an unreviewed top-level declaration')
    instructions, entries, labels = [], {}, {}
    for mode, function in enumerate(functions, 1):
        entries[function.name] = {'mode':mode,'pc':len(instructions)+1,'parameters':function.parameters,
                                  'slots':function.slot_count}
        for instruction in function.instructions:
            if instruction['kind'] == 'mark': labels[instruction['label']] = len(instructions)+1
            else: instructions.append(dict(instruction, function=function.name, pc=len(instructions)+1))
    for instruction in instructions:
        for field in ('target','yes','no'):
            if field in instruction: instruction[field] = labels[instruction[field]]
    return literals, functions, entries, instructions

"""Finite authoring compiler for the complete, explicitly checked lowering policy.

This module is never imported by the runtime. Its instructions are control
blocks subsequently rendered as HIA; they are not precomputed lowering results.
Unsupported Python syntax fails generation instead of falling back to Python.
"""
from __future__ import annotations

import ast
from dataclasses import dataclass


OPS = {
    'GLOBAL': 1, 'ATTR': 2, 'SET_ATTR': 3, 'ITEM': 4, 'SET_ITEM': 5,
    'CALL': 6, 'PACK': 7, 'ITER': 8, 'NEXT': 9, 'TRUTH': 10,
    'BINARY': 11, 'UNARY': 12, 'COMPARE': 13, 'UNPACK': 14,
    'SLICE': 15, 'APPEND': 16, 'IMPORT': 17, 'RAISE': 18,
}
BINARY = {name: i for i, name in enumerate((
    'Add', 'Sub', 'Mult', 'FloorDiv', 'Div', 'Mod', 'Pow',
    'LShift', 'RShift', 'BitOr', 'BitXor', 'BitAnd'), 1)}
COMPARE = {name: i for i, name in enumerate((
    'Eq', 'NotEq', 'Lt', 'LtE', 'Gt', 'GtE', 'In', 'NotIn'), 1)}
UNARY = {'UAdd': 1, 'USub': 2, 'Invert': 3}
PACK = {'List': 1, 'Tuple': 2, 'Set': 3, 'Dict': 4}


@dataclass(frozen=True)
class Ref:
    kind: str
    index: int


@dataclass(frozen=True)
class Raw:
    value: int


class Literals:
    def __init__(self):
        self.values = []
        self.indices = {}
        for value in (None, False, True):
            self.get(value)

    def get(self, value):
        if type(value) not in (type(None), bool, int, str):
            raise ValueError('unsupported literal type: ' + type(value).__name__)
        if type(value) is int and not 0 <= value < 1 << 64:
            raise ValueError('integer literal must use explicit unary/arithmetic construction')
        key = (type(value), value)
        if key not in self.indices:
            self.indices[key] = len(self.values)
            self.values.append(value)
        return Ref('constant', self.indices[key])


class Function:
    def __init__(self, name, node, literals):
        self.name, self.node, self.literals = name, node, literals
        self.instructions = []
        self.locals = {}
        self.slot_count = 0
        self.labels = 0
        self.comp_scopes = []
        self.parameters = [a.arg for a in node.args.args]
        if node.args.posonlyargs or node.args.vararg or node.args.kwonlyargs or node.args.kwarg:
            raise ValueError('unsupported policy signature: ' + name)
        if len(self.parameters) > 4:
            raise ValueError('policy ABI accepts at most four bound arguments')
        for parameter in self.parameters:
            self.local(parameter)
        # Assignment establishes a Python local even before its first value.
        for value in ast.walk(node):
            if isinstance(value, ast.Name) and isinstance(value.ctx, ast.Store):
                self.local(value.id)
            elif isinstance(value, ast.ImportFrom):
                for alias in value.names:
                    self.local(alias.asname or alias.name)

    def temporary(self):
        result = Ref('slot', self.slot_count)
        self.slot_count += 1
        return result

    def local(self, name):
        if name not in self.locals:
            self.locals[name] = self.temporary()
        return self.locals[name]

    def variable(self, name):
        for scope in reversed(self.comp_scopes):
            if name in scope:
                return scope[name]
        return self.locals.get(name)

    def constant(self, value):
        return self.literals.get(value)

    def label(self):
        result = self.name + ':L' + str(self.labels)
        self.labels += 1
        return result

    def mark(self, label):
        self.instructions.append({'kind': 'mark', 'label': label})

    def move(self, destination, value):
        assert destination.kind == 'slot'
        self.instructions.append({'kind': 'move', 'destination': destination, 'value': value})

    def jump(self, label):
        self.instructions.append({'kind': 'jump', 'target': label})

    def effect(self, opcode, arguments, count=1, **extra):
        if len(arguments) > 8 or not 0 <= count <= 3:
            raise ValueError('foreign primitive exceeds the fixed HIA packet ABI')
        destinations = tuple(self.temporary() for _ in range(count))
        self.instructions.append({'kind': 'effect', 'opcode': OPS[opcode],
                                  'arguments': tuple(arguments), 'destinations': destinations, **extra})
        return destinations[0] if count == 1 else destinations

    def truth(self, value, yes, no):
        if value.kind == 'constant':
            literal = self.literals.values[value.index]
            # Literal truth is a static language operation, without foreign hooks.
            self.jump(yes if literal else no)
            return
        self.effect('TRUTH', (value,), count=0)
        self.instructions.append({'kind': 'flag', 'yes': yes, 'no': no})

    def condition(self, node, yes, no):
        if isinstance(node, ast.BoolOp):
            for value in node.values[:-1]:
                onward = self.label()
                self.condition(value, onward if isinstance(node.op, ast.And) else yes,
                               no if isinstance(node.op, ast.And) else onward)
                self.mark(onward)
            self.condition(node.values[-1], yes, no)
            return
        if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not):
            self.condition(node.operand, no, yes)
            return
        if isinstance(node, ast.Compare) and len(node.ops) > 1:
            left = self.expression(node.left)
            for index, (operator, comparator) in enumerate(zip(node.ops, node.comparators)):
                right = self.expression(comparator)
                result = self.compare(operator, left, right)
                onward = yes if index == len(node.ops) - 1 else self.label()
                self.truth(result, onward, no)
                if index != len(node.ops) - 1:
                    self.mark(onward)
                left = right
            return
        self.truth(self.expression(node), yes, no)

    def compare(self, operator, left, right):
        if isinstance(operator, (ast.Is, ast.IsNot)):
            result = self.temporary()
            self.instructions.append({'kind': 'identity', 'destination': result,
                'left': left, 'right': right, 'negate': isinstance(operator, ast.IsNot),
                'true': self.constant(True), 'false': self.constant(False)})
            return result
        return self.effect('COMPARE', (Raw(COMPARE[type(operator).__name__]), left, right))

    def expression(self, node):
        if isinstance(node, ast.Constant):
            return self.constant(node.value)
        if isinstance(node, ast.Name):
            local = self.variable(node.id)
            return local if local is not None else self.effect('GLOBAL', (self.constant(node.id),))
        if isinstance(node, ast.Attribute):
            return self.effect('ATTR', (self.expression(node.value), self.constant(node.attr)))
        if isinstance(node, ast.Subscript):
            value = self.expression(node.value)
            return self.effect('ITEM', (value, self.expression(node.slice)))
        if isinstance(node, ast.Slice):
            return self.effect('SLICE', tuple(self.expression(v) if v is not None else self.constant(None)
                                              for v in (node.lower, node.upper, node.step)))
        if isinstance(node, ast.BinOp):
            return self.effect('BINARY', (Raw(BINARY[type(node.op).__name__]),
                                          self.expression(node.left), self.expression(node.right)))
        if isinstance(node, ast.UnaryOp):
            if isinstance(node.op, ast.Not):
                result, yes, no, done = self.temporary(), self.label(), self.label(), self.label()
                self.condition(node.operand, no, yes)
                self.mark(yes); self.move(result, self.constant(True)); self.jump(done)
                self.mark(no); self.move(result, self.constant(False)); self.mark(done)
                return result
            return self.effect('UNARY', (Raw(UNARY[type(node.op).__name__]), self.expression(node.operand)))
        if isinstance(node, ast.BoolOp):
            result, done = self.temporary(), self.label()
            for index, value in enumerate(node.values):
                observed = self.expression(value); self.move(result, observed)
                if index != len(node.values) - 1:
                    onward = self.label()
                    self.truth(observed, onward if isinstance(node.op, ast.And) else done,
                               done if isinstance(node.op, ast.And) else onward)
                    self.mark(onward)
            self.mark(done)
            return result
        if isinstance(node, ast.IfExp):
            result, yes, no, done = self.temporary(), self.label(), self.label(), self.label()
            self.condition(node.test, yes, no)
            self.mark(yes); self.move(result, self.expression(node.body)); self.jump(done)
            self.mark(no); self.move(result, self.expression(node.orelse)); self.mark(done)
            return result
        if isinstance(node, ast.Compare):
            if len(node.ops) == 1:
                return self.compare(node.ops[0], self.expression(node.left), self.expression(node.comparators[0]))
            result, yes, no, done = self.temporary(), self.label(), self.label(), self.label()
            self.condition(node, yes, no)
            self.mark(yes); self.move(result, self.constant(True)); self.jump(done)
            self.mark(no); self.move(result, self.constant(False)); self.mark(done)
            return result
        if isinstance(node, (ast.List, ast.Tuple, ast.Set, ast.Dict)):
            if isinstance(node, ast.Dict):
                if any(k is None for k in node.keys): raise ValueError('dict expansion is not admitted')
                values = tuple(v for pair in zip(node.keys, node.values) for v in pair)
            else:
                values = node.elts
            observed = tuple(self.expression(v) for v in values)
            return self.effect('PACK', (Raw(PACK[type(node).__name__]), Raw(len(observed))),
                               vector=observed)
        if isinstance(node, (ast.ListComp, ast.DictComp)):
            return self.comprehension(node)
        if isinstance(node, ast.Call):
            if (isinstance(node.func, ast.Name) and node.func.id in ('sum', 'max', 'any')
                    and len(node.args) == 1 and isinstance(node.args[0], ast.GeneratorExp)):
                return self.reduction(node)
            callee = self.expression(node.func)
            if any(isinstance(v, ast.Starred) for v in node.args) or len(node.args) > 4:
                raise ValueError('expanded or long call is outside the finite policy grammar')
            arguments = [self.expression(v) for v in node.args]
            if len(node.keywords) > 1 or any(v.arg is None for v in node.keywords):
                raise ValueError('expanded or multiple keyword call is outside the finite policy grammar')
            key, value = self.constant(None), self.constant(None)
            if node.keywords:
                key = self.constant(node.keywords[0].arg)
                value = self.expression(node.keywords[0].value)
            arguments += [self.constant(None)] * (4 - len(arguments))
            return self.effect('CALL', (callee, Raw(len(node.args)), *arguments, key, value))
        raise ValueError('unsupported policy expression: ' + ast.dump(node))

    def assign(self, target, value):
        if isinstance(target, ast.Name):
            local = self.variable(target.id)
            if local is None: local = self.local(target.id)
            self.move(local, value)
        elif isinstance(target, ast.Attribute):
            self.effect('SET_ATTR', (self.expression(target.value), self.constant(target.attr), value), count=0)
        elif isinstance(target, ast.Subscript):
            self.effect('SET_ITEM', (self.expression(target.value), self.expression(target.slice), value), count=0)
        elif isinstance(target, (ast.Tuple, ast.List)):
            if not 1 <= len(target.elts) <= 3: raise ValueError('unpack arity outside packet profile')
            pieces = self.effect('UNPACK', (value, Raw(len(target.elts))), count=len(target.elts))
            if len(target.elts) == 1: pieces = (pieces,)
            for child, piece in zip(target.elts, pieces): self.assign(child, piece)
        else:
            raise ValueError('unsupported assignment target: ' + ast.dump(target))

    def iterate(self, generators, body, *, first_iterator=None):
        if not generators:
            body(); return
        generator = generators[0]
        if generator.is_async: raise ValueError('async comprehension is not supported')
        iterator = first_iterator or self.effect('ITER', (self.expression(generator.iter),))
        head, found, done = self.label(), self.label(), self.label()
        self.mark(head); value = self.effect('NEXT', (iterator,))
        self.instructions.append({'kind': 'flag', 'yes': found, 'no': done})
        self.mark(found); self.assign(generator.target, value)
        for condition in generator.ifs:
            onward = self.label(); self.condition(condition, onward, head); self.mark(onward)
        self.iterate(generators[1:], body)
        self.jump(head); self.mark(done)

    def scope_for(self, generators):
        names = {v.id for g in generators for v in ast.walk(g.target)
                 if isinstance(v, ast.Name) and isinstance(v.ctx, ast.Store)}
        return {name: self.temporary() for name in sorted(names)}

    def comprehension(self, node):
        # The outer iterable is bound before the comprehension's own locals.
        first = self.effect('ITER', (self.expression(node.generators[0].iter),))
        result = self.effect('PACK', (Raw(PACK['Dict' if isinstance(node, ast.DictComp) else 'List']), Raw(0)), vector=())
        self.comp_scopes.append(self.scope_for(node.generators))
        def body():
            if isinstance(node, ast.DictComp):
                key, value = self.expression(node.key), self.expression(node.value)
                self.effect('SET_ITEM', (result, key, value), count=0)
            else:
                self.effect('APPEND', (result, self.expression(node.elt)), count=0)
        self.iterate(node.generators, body, first_iterator=first)
        self.comp_scopes.pop()
        return result

    def reduction(self, node):
        name, generator = node.func.id, node.args[0]
        if any(k.arg != 'default' for k in node.keywords) or len(node.keywords) > 1:
            raise ValueError('unsupported generator reduction keyword')
        if name != 'max' and node.keywords: raise ValueError('unexpected reduction keyword')
        # These are explicit HIA loops; a hosted Python generator is never built.
        first = self.effect('ITER', (self.expression(generator.generators[0].iter),))
        result, seen, done = self.temporary(), self.temporary(), self.label()
        default = self.expression(node.keywords[0].value) if node.keywords else self.constant(False if name == 'any' else 0)
        self.move(result, default); self.move(seen, self.constant(False))
        self.comp_scopes.append(self.scope_for(generator.generators))
        def body():
            value = self.expression(generator.elt)
            if name == 'sum':
                self.move(result, self.effect('BINARY', (Raw(BINARY['Add']), result, value)))
            elif name == 'any':
                yes, no = self.label(), self.label()
                self.truth(value, yes, no); self.mark(yes)
                self.move(result, self.constant(True)); self.jump(done); self.mark(no)
            else:
                compare, take, onward = self.label(), self.label(), self.label()
                self.truth(seen, compare, take); self.mark(compare)
                self.truth(self.compare(ast.Gt(), value, result), take, onward)
                self.mark(take); self.move(result, value); self.move(seen, self.constant(True))
                self.mark(onward)
        self.iterate(generator.generators, body, first_iterator=first)
        self.comp_scopes.pop(); self.mark(done)
        return result

    def statements(self, nodes):
        for node in nodes:
            if isinstance(node, ast.Expr):
                if not isinstance(node.value, ast.Constant): self.expression(node.value)
            elif isinstance(node, ast.Assign):
                value = self.expression(node.value)
                for target in node.targets: self.assign(target, value)
            elif isinstance(node, ast.AugAssign):
                if isinstance(node.target, ast.Name):
                    old = self.variable(node.target.id); receiver = None
                elif isinstance(node.target, ast.Attribute):
                    receiver = self.expression(node.target.value)
                    old = self.effect('ATTR', (receiver, self.constant(node.target.attr)))
                else:
                    raise ValueError('unsupported augmented assignment target')
                value = self.effect('BINARY', (Raw(128 + BINARY[type(node.op).__name__]), old, self.expression(node.value)))
                if receiver is None: self.assign(node.target, value)
                else: self.effect('SET_ATTR', (receiver, self.constant(node.target.attr), value), count=0)
            elif isinstance(node, ast.If):
                yes, no, done = self.label(), self.label(), self.label()
                self.condition(node.test, yes, no); self.mark(yes)
                self.statements(node.body); self.jump(done); self.mark(no)
                self.statements(node.orelse); self.mark(done)
            elif isinstance(node, ast.For):
                iterator = self.effect('ITER', (self.expression(node.iter),))
                head, found, done = self.label(), self.label(), self.label()
                self.mark(head); value = self.effect('NEXT', (iterator,))
                self.instructions.append({'kind':'flag','yes':found,'no':done})
                self.mark(found); self.assign(node.target, value); self.statements(node.body)
                self.jump(head); self.mark(done); self.statements(node.orelse)
            elif isinstance(node, ast.While):
                head, body, done = self.label(), self.label(), self.label()
                self.mark(head); self.condition(node.test, body, done); self.mark(body)
                self.statements(node.body); self.jump(head); self.mark(done); self.statements(node.orelse)
            elif isinstance(node, ast.Return):
                self.instructions.append({'kind':'return','value':self.expression(node.value) if node.value is not None else self.constant(None)})
            elif isinstance(node, ast.ImportFrom):
                if node.level != 1 or node.module != 'hia_machine_plan' or len(node.names) != 1 or node.names[0].name != 'VALUE_REGISTERS':
                    raise ValueError('only the original explicit plan-register import is admitted')
                value = self.effect('IMPORT', ())
                self.move(self.local(node.names[0].asname or 'VALUE_REGISTERS'), value)
            elif isinstance(node, ast.Raise):
                if node.cause is not None or node.exc is None: raise ValueError('unsupported raise form')
                self.effect('RAISE', (self.expression(node.exc),), count=0)
            elif isinstance(node, ast.Pass):
                pass
            else:
                raise ValueError('unsupported policy statement: ' + ast.dump(node))

    def compile(self):
        self.statements(self.node.body)
        self.instructions.append({'kind':'return','value':self.constant(None)})
        return self


def compile_policy(source):
    tree = ast.parse(source)
    literals, functions = Literals(), []
    for node in tree.body:
        if isinstance(node, ast.FunctionDef):
            functions.append(Function(node.name, node, literals).compile())
        elif isinstance(node, ast.ClassDef) and node.name == '_Function':
            for method in node.body:
                if not isinstance(method, ast.FunctionDef): raise ValueError('unsupported Function class body')
                functions.append(Function('_Function.' + method.name, method, literals).compile())
        elif isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant) and type(node.value.value) is str:
            pass
        else:
            raise ValueError('policy contains an unreviewed top-level declaration')
    instructions, entries, labels = [], {}, {}
    for mode, function in enumerate(functions, 1):
        entries[function.name] = {'mode':mode,'pc':len(instructions)+1,'parameters':function.parameters,
                                  'slots':function.slot_count}
        for instruction in function.instructions:
            if instruction['kind'] == 'mark': labels[instruction['label']] = len(instructions)+1
            else: instructions.append(dict(instruction, function=function.name, pc=len(instructions)+1))
    for instruction in instructions:
        for field in ('target','yes','no'):
            if field in instruction: instruction[field] = labels[instruction[field]]
    return literals, functions, entries, instructions

"""Authoring-only complete Function lowering policy, compiled into HIA continuations.

Runtime packages never execute or import this source. It preserves the exact608
Function and helper AST as the explicit policy input, rather than replay outputs.
"""

def _reject(message, code="E_HIA_PROGRAM_NATIVE"):
    raise HIAProgramNativeRejected(code + ": " + message)

def _words(typ):
    return 2 if typ in BYTE_RESOURCES else 1

def _bounds(typ):
    bits = WIDTHS[typ]
    return (-(1 << (bits - 1)), (1 << (bits - 1)) - 1) if typ.startswith("i") else (0, (1 << bits) - 1)

def _normalize(code, reg, typ):
    """Canonical full-register representation, including dirty incoming highs."""
    if typ == "unit":
        code.mov_imm(reg, 0)
    elif typ == "bool":
        code.alu_imm("and", reg, 1)
    elif typ in WIDTHS and WIDTHS[typ] < 64:
        count = 64 - WIDTHS[typ]
        code.shift_imm("shl", reg, count)
        code.shift_imm("sar" if typ.startswith("i") else "shr", reg, count)

def _prologue(code, frame):
    code.push("rbp")
    code.mov_rr("rbp", "rsp")
    # Touch each 4-KiB interval so a large frame cannot jump a stack guard.
    remaining = frame
    while remaining:
        amount = min(4096, remaining)
        code.alu_imm("sub", "rsp", amount)
        code.load("r11", "rsp", 0)
        remaining -= amount

class _Function:
    def __init__(self, parent, fn, index):
        self.parent, self.fn, self.index = parent, fn, index
        self.c = parent.c
        self.cursor = 8  # saved output-array pointer at rbp-8
        self.slots, self.types = {}, {}
        plan = parent.machine_plan or {}
        self.value_registers = plan.get("value_registers", {}).get(fn["name"], {})
        self.scalar_select = plan.get("instruction_selection", {}).get("scalar_select", "branch")
        self.blocks = {b["id"]: b for b in fn["blocks"]}
        for block in fn["blocks"]:
            definitions = block["params"] + [out for op in block["ops"] for out in op["out"]]
            for value in definitions:
                name, typ = value["name"], value["type"]
                self.slots[name] = self.allocate(_words(typ))
                self.types[name] = typ
        self.edge_words = max((sum(_words(p["type"]) for p in b["params"]) for b in fn["blocks"]), default=0)
        calls = [op for b in fn["blocks"] for op in b["ops"] if op["op"] == "call"]
        self.call_words = max((sum(_words(self.types[a]) for a in op["args"]) for op in calls), default=0)
        self.result_words = max((sum(_words(v["type"]) for v in op["out"]) for op in calls), default=0)
        self.edge_slot = self.allocate(max(1, self.edge_words))
        self.call_slot = self.allocate(max(1, self.call_words))
        self.result_slot = self.allocate(max(1, self.result_words))
        self.temporary = self.allocate(4)
        from .hia_machine_plan import VALUE_REGISTERS
        # Keep canonical staging/temporary locations disjoint from saved ABI
        # registers. A selected SSA value lives only in its checked register;
        # its canonical slot is reserved but no stale spill is ever read.
        self.saved_registers = {reg: self.allocate(1) for reg in VALUE_REGISTERS
                                if reg in self.value_registers.values()}
        # v4 r8/r9 values are caller-clobbered and are never saved here. The
        # independent plan checker restricts the entire function to its exact
        # leaf inventory (including exclusion of buffer.swap's implicit r8).
        self.frame = (self.cursor + 15) & -16
        if self.frame > MAX_FRAME_BYTES:
            _reject("function stack frame exceeds 64 KiB: " + fn["name"], "E_HIA_PROGRAM_LIMIT")
        self.trap = self.label("trap")

    def allocate(self, words):
        self.cursor += 8 * words
        return -self.cursor

    def label(self, suffix):
        return self.parent.label("fn" + str(self.index) + "_" + suffix)

    def block_label(self, name):
        return "fn" + str(self.index) + "_block_" + name

    def load(self, name, reg="rax", word=0):
        if name in self.value_registers:
            if word:
                _reject("multiword value cannot use the scalar register plan", "E_HIA_MACHINE_PLAN")
            self.c.mov_rr(reg, self.value_registers[name])
        else:
            self.c.load(reg, "rbp", self.slots[name] + word * 8)

    def store(self, name, reg="rax", word=0):
        if name in self.value_registers:
            if word:
                _reject("multiword value cannot use the scalar register plan", "E_HIA_MACHINE_PLAN")
            self.c.mov_rr(self.value_registers[name], reg)
        else:
            self.c.store("rbp", self.slots[name] + word * 8, reg)

    def immediate(self, name, value, word=0):
        self.c.mov_imm("rax", int(value) & ((1 << 64) - 1))
        self.store(name, word=word)

    def copy(self, source, destination):
        for i in range(_words(self.types[source])):
            self.load(source, word=i)
            self.store(destination, word=i)

    def fail_if(self, condition):
        self.c.jcc(condition, self.trap)

    def compare_imm(self, register, value):
        self.c.mov_imm("r11", value & ((1 << 64) - 1))
        self.c.cmp(register, "r11")

    def range_check(self, register, typ, source=None):
        source = typ if source is None else source
        lo, hi = _bounds(typ)
        before_lo, before_hi = _bounds(source)
        signed = source.startswith("i")
        if lo > before_lo:
            self.compare_imm(register, lo)
            self.fail_if("l" if signed else "b")
        if hi < before_hi:
            self.compare_imm(register, hi)
            self.fail_if("g" if signed else "a")

    def narrow_result(self, typ, checked=False):
        if checked and WIDTHS[typ] < 64:
            # Arithmetic used full-width canonical registers; enforce original width.
            self.range_check("rax", typ, "i64" if typ.startswith("i") else "u64")
        _normalize(self.c, "rax", typ)

    def condition_value(self, condition):
        self.c.setcc(condition, "rax")

    def edge(self, target, arguments):
        # All sources are staged first. Backedges may permute their own slots.
        n = 0
        for arg in arguments:
            for word in range(_words(self.types[arg])):
                self.load(arg, word=word)
                self.c.store("rbp", self.edge_slot + n * 8, "rax")
                n += 1
        n = 0
        for param in self.blocks[target]["params"]:
            for word in range(_words(param["type"])):
                self.c.load("rax", "rbp", self.edge_slot + n * 8)
                self.store(param["name"], word=word)
                n += 1
        self.c.jmp(self.block_label(target))

    def operation(self, ins):
        c = self.c
        op, args, attrs = ins["op"], ins["args"], ins["attrs"]
        out = [v["name"] for v in ins["out"]]
        typ = self.types[args[0]] if args else None
        if op == "const":
            self.immediate(out[0], 0 if attrs["value"] is None else attrs["value"])
        elif op.startswith("int.") and op.split(".")[1] in {"add", "sub", "mul"}:
            action, mode = op.split(".")[1:]
            checked = mode == "checked"
            self.load(args[0]); self.load(args[1], "rcx")
            if action == "mul":
                if checked and not typ.startswith("i"):
                    c.mul("rcx")
                    c.test("rdx", "rdx"); self.fail_if("ne")
                else:
                    c.imul_rr("rax", "rcx")
                    if checked:
                        self.fail_if("o")
            else:
                getattr(c, action)("rax", "rcx")
                if checked:
                    self.fail_if("o" if typ.startswith("i") else "b")
            self.narrow_result(typ, checked)
            self.store(out[0])
        elif op in {"int.div.checked", "int.rem.checked"}:
            self.load(args[0]); self.load(args[1], "rcx")
            c.test("rcx", "rcx"); self.fail_if("e")
            if typ.startswith("i"):
                safe = self.label("division")
                self.compare_imm("rax", _bounds(typ)[0]); c.jcc("ne", safe)
                self.compare_imm("rcx", -1); self.fail_if("e")
                c.label(safe); c.cqo(); c.idiv("rcx")
            else:
                c.xor("rdx", "rdx"); c.div("rcx")
            if op == "int.rem.checked":
                c.mov_rr("rax", "rdx")
            self.store(out[0])
        elif op in {"int.shl.checked", "int.shr.checked"}:
            self.load(args[0]); self.load(args[1], "rcx")
            self.compare_imm("rcx", WIDTHS[typ]); self.fail_if("ae")
            c.shift_cl("shl" if op == "int.shl.checked" else "sar" if typ.startswith("i") else "shr", "rax")
            self.narrow_result(typ); self.store(out[0])
        elif op == "int.neg.checked":
            self.load(args[0])
            if typ.startswith("i"):
                c.neg("rax"); self.fail_if("o")
                self.narrow_result(typ, True)
            else:
                c.test("rax", "rax"); self.fail_if("ne")
            self.store(out[0])
        elif op.startswith("bit."):
            self.load(args[0])
            action = op.split(".")[1]
            if action == "not":
                c.bitnot("rax")
            else:
                self.load(args[1], "rcx")
                getattr(c, {"and": "and_", "or": "or_", "xor": "xor"}[action])("rax", "rcx")
            self.narrow_result(typ); self.store(out[0])
        elif op.startswith("compare."):
            self.load(args[0]); self.load(args[1], "rcx"); c.cmp("rax", "rcx")
            predicates = ({"eq": "e", "ne": "ne", "lt": "l", "le": "le", "gt": "g", "ge": "ge"}
                          if typ.startswith("i") else
                          {"eq": "e", "ne": "ne", "lt": "b", "le": "be", "gt": "a", "ge": "ae"})
            self.condition_value(predicates[op.split(".")[1]]); self.store(out[0])
        elif op.startswith("bool."):
            self.load(args[0])
            if op == "bool.not":
                c.alu_imm("xor", "rax", 1)
            else:
                self.load(args[1], "rcx")
                getattr(c, "and_" if op == "bool.and" else "or_")("rax", "rcx")
            self.store(out[0])
        elif op == "int.cast":
            self.load(args[0]); dest = self.types[out[0]]
            if attrs["mode"] == "checked":
                self.range_check("rax", dest, typ)
            _normalize(c, "rax", dest); self.store(out[0])
        elif op == "select":
            if self.scalar_select == "cmov_scalar":
                # Core SELECT admits only already-defined nonresource values.
                # Register-only CMOV adds no conditional memory read or effect;
                # loading these scalar representations uses flag-preserving MOV.
                self.load(args[0]); c.test("rax", "rax")
                self.load(args[2]); self.load(args[1], "rcx")
                c.cmov("ne", "rax", "rcx"); self.store(out[0])
            else:
                yes, done = self.label("select_yes"), self.label("select_done")
                self.load(args[0]); c.test("rax", "rax"); c.jcc("ne", yes)
                self.copy(args[2], out[0]); c.jmp(done)
                c.label(yes); self.copy(args[1], out[0]); c.label(done)
        elif op == "call":
            n = 0
            for arg in args:
                for word in range(_words(self.types[arg])):
                    self.load(arg, word=word); c.store("rbp", self.call_slot + n * 8, "rax"); n += 1
            c.lea("rdi", "rbp", self.call_slot)
            c.lea("rsi", "rbp", self.result_slot)
            c.call(self.parent.function_symbol(attrs["function"]))
            n = 0
            for name in out:
                for word in range(_words(self.types[name])):
                    c.load("rax", "rbp", self.result_slot + n * 8); self.store(name, word=word); n += 1
        elif op in {"owner.move", "borrow.read", "borrow.mut"}:
            self.copy(args[0], out[0])
        elif op == "loan.end":
            pass  # Permission/lifetime transitions were independently verified.
        elif op in {"buffer.new", "buffer.try_new"}:
            self.allocate_buffer(args[0], out, op == "buffer.new")
        elif op == "buffer.len":
            self.load(args[0], word=1); self.store(out[0])
        elif op == "owner.drop":
            if typ == "chain":
                self.drop_chain(args[0])
            else:
                done = self.label("drop_done")
                self.load(args[0], "rdi"); c.test("rdi", "rdi"); c.jcc("e", done)
                c.call("free"); c.label(done)
        elif op in {"buffer.load", "buffer.store"}:
            self.load(args[0], "rdx", 1); self.load(args[1], "rcx")
            c.cmp("rcx", "rdx"); self.fail_if("ae")
            self.load(args[0]); c.add("rax", "rcx")
            if op == "buffer.load":
                c.load_u8("rax", "rax"); self.store(out[0])
            else:
                self.load(args[2], "rcx"); c.store_u8("rax", 0, "rcx")
        elif op == "buffer.swap":
            # Both checks precede either write, including equal-index operations.
            self.load(args[0], "rdx", 1)
            self.load(args[1], "rcx"); c.cmp("rcx", "rdx"); self.fail_if("ae")
            self.load(args[2], "r8"); c.cmp("r8", "rdx"); self.fail_if("ae")
            self.load(args[0], "rdi"); c.mov_rr("rsi", "rdi")
            c.add("rdi", "rcx"); c.add("rsi", "r8")
            c.load_u8("rax", "rdi"); c.load_u8("rcx", "rsi")
            c.store_u8("rdi", 0, "rcx"); c.store_u8("rsi", 0, "rax")
        elif op in {"buffer.fill", "buffer.copy", "buffer.move_within", "buffer.copy_range", "buffer.fill_range"}:
            self.bulk(op, args)
        elif op == "chain.empty":
            self.immediate(out[0], 0)
        elif op == "chain.is_empty":
            self.load(args[0]); c.test("rax", "rax"); self.condition_value("e"); self.store(out[0])
        elif op in {"chain.head_read", "chain.head_mut"}:
            self.load(args[0], "rdx"); c.test("rdx", "rdx"); self.fail_if("e")
            for word in range(2):
                c.load("rax", "rdx", word * 8); self.store(out[0], word=word)
        elif op == "chain.try_push":
            self.push_chain(args, out)
        elif op == "chain.pop":
            self.pop_chain(args[0], out)
        else:
            _reject("opcode lacks a direct machine lowering: " + op)

    def allocate_buffer(self, size, out, trapping):
        c = self.c
        empty, failed, done = self.label("alloc_empty"), self.label("alloc_failed"), self.label("alloc_done")
        self.load(size, "rsi")
        c.test("rsi", "rsi"); c.jcc("e", empty)
        self.compare_imm("rsi", (1 << 63) - 1); c.jcc("a", failed)
        c.mov_imm("rdi", 1); c.call("calloc")
        c.test("rax", "rax"); c.jcc("e", failed)
        self.store(out[0]); self.load(size); self.store(out[0], word=1)
        if not trapping:
            self.immediate(out[1], 1)
        c.jmp(done)
        c.label(empty)
        self.immediate(out[0], 0); self.immediate(out[0], 0, 1)
        if not trapping:
            self.immediate(out[1], 1)
        c.jmp(done)
        c.label(failed)
        if trapping:
            c.jmp(self.trap)
        else:
            self.immediate(out[0], 0); self.immediate(out[0], 0, 1); self.immediate(out[1], 0)
        c.label(done)

    def range_guard(self, buffer, offset, size):
        c = self.c
        self.load(buffer, "rax", 1)
        self.load(offset, "rcx"); c.cmp("rcx", "rax"); self.fail_if("a")
        c.sub("rax", "rcx")
        self.load(size, "rcx"); c.cmp("rcx", "rax"); self.fail_if("a")

    def bulk(self, op, args):
        c = self.c
        done = self.label("bulk_done")
        if op == "buffer.fill":
            self.load(args[0], "rdx", 1)
        elif op == "buffer.copy":
            self.load(args[2], "rdx")
            for owner in args[:2]:
                self.load(owner, "rax", 1); c.cmp("rdx", "rax"); self.fail_if("a")
        elif op == "buffer.fill_range":
            self.range_guard(args[0], args[1], args[2]); self.load(args[2], "rdx")
        elif op == "buffer.move_within":
            self.range_guard(args[0], args[1], args[3]); self.range_guard(args[0], args[2], args[3])
            self.load(args[3], "rdx")
        else:
            self.range_guard(args[0], args[2], args[4]); self.range_guard(args[1], args[3], args[4])
            self.load(args[4], "rdx")
        c.test("rdx", "rdx"); c.jcc("e", done)
        # Empty operations skip even derived pointer formation and libc calls.
        self.load(args[0], "rdi")
        if op in {"buffer.fill", "buffer.fill_range"}:
            if op == "buffer.fill_range":
                self.load(args[1], "rax"); c.add("rdi", "rax")
            self.load(args[1] if op == "buffer.fill" else args[3], "rsi")
            c.call("memset")
        else:
            self.load(args[0] if op == "buffer.move_within" else args[1], "rsi")
            if op in {"buffer.move_within", "buffer.copy_range"}:
                i = 1 if op == "buffer.move_within" else 2
                self.load(args[i], "rax"); c.add("rdi", "rax")
                self.load(args[i + 1], "rax"); c.add("rsi", "rax")
            c.call("memmove" if op == "buffer.move_within" else "memcpy")
        c.label(done)

    def push_chain(self, args, out):
        c = self.c
        failed, done = self.label("push_failed"), self.label("push_done")
        c.mov_imm("rdi", 24); c.call("malloc")
        c.test("rax", "rax"); c.jcc("e", failed)
        self.store(out[0]); c.mov_rr("rdx", "rax")
        self.load(args[1]); c.store("rdx", 0, "rax")
        self.load(args[1], word=1); c.store("rdx", 8, "rax")
        self.load(args[0]); c.store("rdx", 16, "rax")
        self.immediate(out[1], 0); self.immediate(out[1], 0, 1); self.immediate(out[2], 1)
        c.jmp(done)
        c.label(failed)
        self.copy(args[0], out[0]); self.copy(args[1], out[1]); self.immediate(out[2], 0)
        c.label(done)

    def pop_chain(self, arg, out):
        c = self.c
        empty, done = self.label("pop_empty"), self.label("pop_done")
        self.load(arg, "rdi"); c.test("rdi", "rdi"); c.jcc("e", empty)
        for word in range(2):
            c.load("rax", "rdi", word * 8); self.store(out[1], word=word)
        c.load("rax", "rdi", 16); self.store(out[0])
        c.call("free"); self.immediate(out[2], 1); c.jmp(done)
        c.label(empty)
        self.immediate(out[0], 0); self.immediate(out[1], 0); self.immediate(out[1], 0, 1); self.immediate(out[2], 0)
        c.label(done)

    def drop_chain(self, arg):
        c = self.c
        loop, node, done = self.label("chain_drop_loop"), self.label("chain_drop_node"), self.label("chain_drop_done")
        self.load(arg); c.store("rbp", self.temporary, "rax")
        c.label(loop)
        c.load("rdx", "rbp", self.temporary); c.test("rdx", "rdx"); c.jcc("e", done)
        c.load("rax", "rdx", 16); c.store("rbp", self.temporary + 8, "rax")
        c.load("rdi", "rdx", 0); c.test("rdi", "rdi"); c.jcc("e", node)
        c.call("free")
        c.label(node)
        c.load("rdi", "rbp", self.temporary); c.call("free")
        c.load("rax", "rbp", self.temporary + 8); c.store("rbp", self.temporary, "rax")
        c.jmp(loop); c.label(done)

    def render(self):
        c = self.c
        begin = len(c.data)
        _prologue(c, self.frame)
        for register, slot in self.saved_registers.items():
            c.store("rbp", slot, register)
        c.store("rbp", -8, "rsi")
        n = 0
        for param in self.fn["params"]:
            for word in range(_words(param["type"])):
                c.load("rax", "rdi", n * 8); self.store(param["name"], word=word); n += 1
        c.jmp(self.block_label(self.fn["entry"]))
        for block in self.parent.ordered_blocks(self.fn):
            c.label(self.block_label(block["id"]))
            for ins in block["ops"]:
                self.operation(ins)
            term = block["term"]
            if term["op"] == "jump":
                self.edge(term["target"], term["args"])
            elif term["op"] == "branch":
                other = self.label("branch_else")
                self.load(term["cond"]); c.test("rax", "rax"); c.jcc("e", other)
                self.edge(term["then"]["target"], term["then"]["args"])
                c.label(other); self.edge(term["else"]["target"], term["else"]["args"])
            elif term["op"] == "trap":
                c.jmp(self.trap)
            elif term["op"] == "ret":
                c.load("r10", "rbp", -8)
                n = 0
                for arg in term["values"]:
                    for word in range(_words(self.types[arg])):
                        self.load(arg, word=word); c.store("r10", n * 8, "rax"); n += 1
                for register, slot in self.saved_registers.items():
                    c.load(register, "rbp", slot)
                c.leave(); c.ret()
            else:
                _reject("unknown native terminator")
            if len(c.data) > MAX_TEXT_BYTES:
                _reject("direct code exceeds the 16 MiB text budget", "E_HIA_PROGRAM_LIMIT")
        c.label(self.trap); c.call("abort"); c.ud2()
        self.parent.symbols.append({"name": self.parent.function_symbol(self.fn["name"]),
                                    "offset": begin, "size": len(c.data) - begin, "global": False})
        self.parent.frames.append((self.fn["name"], self.frame))

def _native_globals():
    return {'WIDTHS': {'i8': 8, 'i16': 16, 'i32': 32, 'i64': 64, 'u8': 8, 'u16': 16, 'u32': 32, 'u64': 64, 'isize': 64, 'usize': 64}, 'BYTE_RESOURCES': ('buffer', 'readbuf', 'mutbuf'), 'MAX_TEXT_BYTES': 16777216, 'MAX_FRAME_BYTES': 65536}

"""Render complete Core Function control as bounded, separate HIA units.

Only this authoring tool imports the finite source compiler. Runtime uses the
resulting HIA images and ABI metadata; it never executes the authoring policy.
"""
from __future__ import annotations

import ast
import json
from pathlib import Path

from hepta.hia_agent_assembly import render_assembly
from tools.generate_hia_selfhost import Builder, compact_authoring_cfg, total_scalar_functions
from tools.hia_core_lowering_ir import Ref, Raw, compile_policy

ROOT = Path(__file__).resolve().parents[1]
POLICY = ROOT / 'tools/hia_core_lowering_policy.py'
ABI = 0xfffffffd
MAGIC = int.from_bytes(b'HIALOW01', 'little')
POOL_MAGIC = int.from_bytes(b'HIALIT01', 'little')
CHUNK = 64
GROUP = 8
SLOTS = 1024
INTERNAL = 4
REQUEST = 1
HANDOFF = 2
FINISHED = 0


def helpers():
    result = []
    for name, typ in (('word', 'readbuf'), ('get', 'mutbuf')):
        lines = ['def ' + name + '(b:' + typ + ', at:u64) -> u64:']
        lines.append('    value = 0')
        for i in range(8):
            lines.append('    value = value | (byte(b, at + ' + str(i) + ') << ' + str(8 * i) + ')')
        lines.append('    return value')
        result.append('\n'.join(lines))
    lines = ['def put(b:mutbuf, at:u64, value:u64) -> u64:']
    for i in range(8):
        lines.append('    store(b, at + ' + str(i) + ', (value >> ' + str(8 * i) + ') & 255)')
    lines.append('    return 0')
    result.append('\n'.join(lines))
    return '\n\n'.join(result) + '\n'


def value_text(value):
    if isinstance(value, Raw):
        return str(value.value)
    if not isinstance(value, Ref):
        raise TypeError('unknown finite operand')
    if value.kind == 'constant':
        return str(value.index + 1)
    if value.kind == 'slot':
        return 'get(w, ' + str(SLOTS + value.index * 8) + ')'
    raise ValueError('unknown reference class')


def put_slot(destination, value):
    if destination.kind != 'slot':
        raise ValueError('invalid lowering destination')
    return 'put(w, ' + str(SLOTS + destination.index * 8) + ', ' + value + ')'


def effect_lines(instruction):
    arguments = instruction['arguments']
    vector = instruction.get('vector', ())
    destinations = instruction['destinations']
    lines = [
        'if get(w, 16) == 18446744073709551615:',
        '    return ' + str(ABI),
        'put(w, 16, get(w, 16) + 1)',
        'put(w, 8, 1)',
        'put(w, 24, ' + str(instruction['pc'] + 1) + ')',
        'put(w, 48, ' + str(instruction['opcode']) + ')',
        'put(w, 56, ' + str(len(destinations)) + ')',
    ]
    for i in range(3):
        offset = SLOTS + destinations[i].index * 8 if i < len(destinations) else 0
        lines.append('put(w, ' + str(64 + i * 8) + ', ' + str(offset) + ')')
    header = (MAGIC, None, instruction['opcode'], len(arguments), len(vector),
              len(destinations), instruction['pc'], 0)
    for i, number in enumerate(header):
        text = 'get(w, 16)' if number is None else str(number)
        lines.append('put(o, ' + str(i * 8) + ', ' + text + ')')
    for i in range(8):
        text = value_text(arguments[i]) if i < len(arguments) else '0'
        lines.append('put(o, ' + str(64 + i * 8) + ', ' + text + ')')
    for i, value in enumerate(vector):
        lines.append('put(o, ' + str(128 + i * 8) + ', ' + value_text(value) + ')')
    lines.append('return 1')
    return lines


def instruction_lines(instruction):
    kind, pc = instruction['kind'], instruction['pc']
    if kind == 'effect':
        return effect_lines(instruction)
    if kind == 'return':
        return [
            'put(o, 0, ' + str(MAGIC) + ')',
            'put(o, 8, get(w, 16))',
            'put(o, 16, 0)',
            'put(o, 24, ' + value_text(instruction['value']) + ')',
            'put(w, 8, 3)',
            'return 0',
        ]
    if kind == 'move':
        lines = [put_slot(instruction['destination'], value_text(instruction['value']))]
        target = pc + 1
    elif kind == 'jump':
        lines, target = [], instruction['target']
    elif kind == 'flag':
        return ['if get(w, 40) != 0:',
                '    put(w, 24, ' + str(instruction['yes']) + ')',
                'else:',
                '    put(w, 24, ' + str(instruction['no']) + ')',
                'return 4']
    elif kind == 'identity':
        operator = '!=' if instruction['negate'] else '=='
        return ['if ' + value_text(instruction['left']) + ' ' + operator + ' ' + value_text(instruction['right']) + ':',
                '    ' + put_slot(instruction['destination'], value_text(instruction['true'])),
                'else:',
                '    ' + put_slot(instruction['destination'], value_text(instruction['false'])),
                'put(w, 24, ' + str(pc + 1) + ')',
                'return 4']
    else:
        raise ValueError('unrendered lowering instruction: ' + kind)
    return lines + ['put(w, 24, ' + str(target) + ')', 'return 4']


def start_source(entries):
    groups = [list(entries.items())[i:i + 4] for i in range(0, len(entries), 4)]
    functions = []
    dispatch = ['def start(s:readbuf, w:mutbuf) -> u32:']
    for group_index, group in enumerate(groups):
        dispatch += ['    if word(s, 24) <= ' + str(group[-1][1]['mode']) + ':',
                     '        return start_' + str(group_index) + '(s, w)']
        lines = ['def start_' + str(group_index) + '(s:readbuf, w:mutbuf) -> u32:']
        for name, entry in group:
            count = len(entry['parameters'])
            lines += ['    if word(s, 24) == ' + str(entry['mode']) + ':',
                      '        if word(s, 32) != ' + str(count) + ':',
                      '            return ' + str(ABI)]
            for i in range(4):
                operator = '==' if i < count else '!='
                lines += ['        if word(s, ' + str(40 + i * 8) + ') ' + operator + ' 0:',
                          '            return ' + str(ABI)]
            for i in range(count):
                lines.append('        put(w, ' + str(SLOTS + i * 8) + ', word(s, ' + str(40 + i * 8) + '))')
            lines += [
                '        put(w, 0, ' + str(MAGIC) + ')',
                '        put(w, 8, 0)',
                '        put(w, 16, 0)',
                '        put(w, 24, ' + str(entry['pc']) + ')',
                '        put(w, 32, ' + str(entry['mode']) + ')',
                '        put(w, 40, 0)',
                '        put(w, 48, 0)',
                '        put(w, 56, 0)',
                '        put(w, 64, 0)',
                '        put(w, 72, 0)',
                '        put(w, 80, 0)',
                '        put(w, 88, 0)',
                '        return 0',
            ]
        lines.append('    return ' + str(ABI))
        functions.append('\n'.join(lines))
    dispatch.append('    return ' + str(ABI))
    return '\n\n'.join(['\n'.join(dispatch), *functions]) + '\n'


def main_source(unit, first, last, total, workspace, output):
    # The sequence is advanced for each effect and each cross-unit handoff.
    # The private continuation is the sole authority for resume destinations.
    return f'''
def lower(s:readbuf, o:mutbuf, w:mutbuf) -> u32:
    if length(s) != 128 or length(w) < {workspace} or length(o) < {output}:
        return {ABI}
    if word(s, 0) != {MAGIC}:
        return {ABI}
    i = 72
    while i < 128:
        if word(s, i) != 0:
            return {ABI}
        i = i + 8
    command = word(s, 8)
    if command == 0:
        if {unit} != 0 or get(w, 0) != 0 or get(w, 8) != 0 or word(s, 16) != 0:
            return {ABI}
        if start(s, w) != 0:
            return {ABI}
    else:
        if get(w, 0) != {MAGIC} or word(s, 16) != get(w, 16):
            return {ABI}
        if command == 1:
            if get(w, 8) != 1 or word(s, 24) != get(w, 56):
                return {ABI}
            if word(s, 32) > 1 or word(s, 64) != 0:
                return {ABI}
            opcode = get(w, 48)
            if opcode != 9 and opcode != 10 and word(s, 32) != 0:
                return {ABI}
            count = get(w, 56)
            if count > 3:
                return {ABI}
            i = 0
            while i < 3:
                if i < count:
                    if word(s, 40 + i * 8) == 0:
                        return {ABI}
                else:
                    if word(s, 40 + i * 8) != 0:
                        return {ABI}
                i = i + 1
            if opcode == 9 and word(s, 32) == 0 and word(s, 40) != 1:
                return {ABI}
            i = 0
            while i < count:
                put(w, get(w, 64 + i * 8), word(s, 40 + i * 8))
                i = i + 1
            put(w, 40, word(s, 32))
            put(w, 8, 0)
        else:
            if command != 2 or get(w, 8) != 2 or get(w, 88) != {unit} or word(s, 24) != {unit}:
                return {ABI}
            if word(s, 32) != 0 or word(s, 40) != 0 or word(s, 48) != 0 or word(s, 56) != 0 or word(s, 64) != 0:
                return {ABI}
            put(w, 8, 0)
    while True:
        pc = get(w, 24)
        if pc == 0 or pc > {total}:
            return {ABI}
        if pc < {first} or pc > {last}:
            if get(w, 16) == 18446744073709551615:
                return {ABI}
            target = (pc - 1) >> 6
            put(w, 16, get(w, 16) + 1)
            put(w, 8, 2)
            put(w, 88, target)
            put(o, 0, {MAGIC})
            put(o, 8, get(w, 16))
            put(o, 16, 19)
            put(o, 24, target)
            return 2
        result = dispatch(w, o)
        if result != 4:
            return result
    return {ABI}
'''


def unit_source(unit, selected, entries, total, workspace, output):
    first, last = selected[0]['pc'], selected[-1]['pc']
    chunks = [selected[i:i + GROUP] for i in range(0, len(selected), GROUP)]
    main = main_source(unit, first, last, total, workspace, output)
    leaves = []
    for number, group in enumerate(chunks):
        lines = ['def group_' + str(number) + '(w:mutbuf, o:mutbuf) -> u32:',
                 '    pc = get(w, 24)']
        for instruction in group:
            lines.append('    if pc == ' + str(instruction['pc']) + ':')
            lines += ['        ' + line for line in instruction_lines(instruction)]
        lines.append('    return ' + str(ABI))
        leaves.append('\n'.join(lines))
    lines = ['def dispatch(w:mutbuf, o:mutbuf) -> u32:',
             '    pc = get(w, 24)']
    for number, group in enumerate(chunks):
        lines += ['    if pc <= ' + str(group[-1]['pc']) + ':',
                  '        return group_' + str(number) + '(w, o)']
    lines.append('    return ' + str(ABI))
    # Initial mode admission exists in unit zero only; other units cannot start.
    startup = start_source(entries) if unit == 0 else (
        'def start(s:readbuf, w:mutbuf) -> u32:\n    return ' + str(ABI) + '\n')
    return main + '\n' + startup + '\n' + '\n\n'.join(leaves + ['\n'.join(lines)]) + '\n' + helpers()


def pool_wire(values):
    data = bytearray(POOL_MAGIC.to_bytes(8, 'little') + len(values).to_bytes(8, 'little'))
    for value in values:
        if value is None:
            kind, word, tail = 0, 0, b''
        elif type(value) is bool:
            kind, word, tail = 1, int(value), b''
        elif type(value) is int:
            kind, word, tail = 2, value, b''
        elif type(value) is str:
            raw = value.encode('utf-8')
            kind, word, tail = 3, len(raw), raw + b'\0' * (-len(raw) % 8)
        else:
            raise ValueError('literal escaped the finite typed pool')
        data += kind.to_bytes(8, 'little') + word.to_bytes(8, 'little') + tail
    return bytes(data)


def pool_source(raw):
    # Literal bytes are authored as HIA writes, not a hosted policy lookup table.
    chunks = [raw[i:i + 192] for i in range(0, len(raw), 192)]
    lines = [
        'def literals(s:readbuf, o:mutbuf, w:mutbuf) -> u32:',
        '    if length(s) != 0 or length(w) != 0 or length(o) < ' + str(len(raw)) + ':',
        '        return ' + str(ABI),
    ]
    for index in range(len(chunks)):
        lines.append('    write_' + str(index) + '(o)')
    lines.append('    return ' + str(len(raw)))
    functions = ['\n'.join(lines)]
    for index, chunk in enumerate(chunks):
        lines = ['def write_' + str(index) + '(o:mutbuf) -> u64:']
        for i in range(0, len(chunk), 8):
            word = int.from_bytes(chunk[i:i + 8], 'little')
            lines.append('    put(o, ' + str(index * 192 + i) + ', ' + str(word) + ')')
        lines.append('    return 0')
        functions.append('\n'.join(lines))
    # Only put is used by the literal owner.
    functions.append(helpers().split('def put(', 1)[1])
    functions[-1] = 'def put(' + functions[-1]
    return '\n\n'.join(functions) + '\n'


def document(source, module):
    nodes = ast.parse(source).body
    names = {node.name: 'f' + str(i) for i, node in enumerate(nodes)}
    signatures = {node.name: ([a.annotation.id for a in node.args.args], node.returns.id) for node in nodes}
    total = total_scalar_functions(nodes)
    functions = []
    for node in nodes:
        builder = Builder(node, names, signatures, total)
        builder.statements(node.body)
        functions.append({'name': names[node.name],
                          'params': [builder.param(value) for value in builder.params],
                          'returns': [builder.returns],
                          'effects': ['read', 'write', 'trap'],
                          'entry': 'b0', 'blocks': builder.blocks})
    return compact_authoring_cfg({'schema': 'hepta.hia.program.v8', 'module': module, 'functions': functions})


def generated():
    literals, functions, entries, instructions = compile_policy(POLICY.read_text())
    if CHUNK != 64:
        raise ValueError('the native unit route is fixed to 64 control instructions')
    if not instructions:
        raise ValueError('empty native lowering policy')
    maximum_slots = max(function.slot_count for function in functions)
    workspace = (SLOTS + maximum_slots * 8 + 63) & -64
    maximum_vector = max((len(item.get('vector', ())) for item in instructions), default=0)
    output = (128 + maximum_vector * 8 + 63) & -64
    wire = pool_wire(literals.values)
    sources = [('core_lowering_pool', pool_source(wire))]
    units = []
    for unit, at in enumerate(range(0, len(instructions), CHUNK)):
        name = 'core_lowering_' + f'{unit:03d}'
        units.append(name)
        sources.append((name, unit_source(unit, instructions[at:at + CHUNK], entries,
                                         len(instructions), workspace, output)))
    abi = {
        'schema': 'hepta.hia.core-lowering-abi.v1',
        'protocol_magic': MAGIC,
        'pool_magic': POOL_MAGIC,
        'packet_bytes': 128,
        'workspace_bytes': workspace,
        'output_bytes': output,
        'pool_bytes': len(wire),
        'literal_count': len(literals.values),
        'units': units,
        'modes': {name: {'number': entry['mode'], 'arity': len(entry['parameters'])}
                  for name, entry in entries.items()},
    }
    return sources, abi


def write(output, metadata):
    sources, abi = generated()
    output.mkdir(parents=True, exist_ok=True)
    for name, source in sources:
        assembly = render_assembly(document(source, name))
        (output / (name + '.hiaasm')).write_text(assembly)
    metadata.write_text(json.dumps(abi, indent=2, sort_keys=True) + '\n')
    return [str(output / (name + '.hiaasm')) for name, _ in sources]


if __name__ == '__main__':
    import argparse
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output', type=Path, default=ROOT / 'examples/hia_bootstrap')
    parser.add_argument('--metadata', type=Path, default=ROOT / 'hepta/hia_core_lowering_abi.json')
    arguments = parser.parse_args()
    for path in write(arguments.output, arguments.metadata):
        print(path)

"""Primitive observation bridge for complete HIA Function lowering.

This development module contains no Function lowering decisions. HIA chooses
each primitive, operand handle, continuation and branch. Authoring policy and IR
modules are never imported here. Source-bound bundle admission and the ordinary
entry selector are still pending in this static draft.
"""
from __future__ import annotations

import builtins
import ctypes
import operator
import struct

MAGIC = int.from_bytes(b'HIALOW01', 'little')
POOL_MAGIC = int.from_bytes(b'HIALIT01', 'little')
ABI = 0xfffffffd
FRAME = struct.Struct('<16Q')

_BINARY = {
    1: operator.add, 2: operator.sub, 3: operator.mul, 4: operator.floordiv,
    5: operator.truediv, 6: operator.mod, 7: operator.pow, 8: operator.lshift,
    9: operator.rshift, 10: operator.or_, 11: operator.xor, 12: operator.and_,
    129: operator.iadd, 130: operator.isub, 131: operator.imul,
    132: operator.ifloordiv, 133: operator.itruediv, 134: operator.imod,
    135: operator.ipow, 136: operator.ilshift, 137: operator.irshift,
    138: operator.ior, 139: operator.ixor, 140: operator.iand,
}
_COMPARE = {
    1: operator.eq, 2: operator.ne, 3: operator.lt, 4: operator.le,
    5: operator.gt, 6: operator.ge,
}
_UNARY = {1: operator.pos, 2: operator.neg, 3: operator.invert}


def _in(left, right):
    return left in right


def _not_in(left, right):
    return left not in right


_COMPARE.update({7: _in, 8: _not_in})


def _decode_pool(raw, expected_count):
    if type(raw) is not bytes or len(raw) < 16:
        raise RuntimeError('native lowering literal packet is missing')
    magic, count = struct.unpack_from('<QQ', raw)
    if magic != POOL_MAGIC or count != expected_count:
        raise RuntimeError('native lowering literal identity differs')
    values, offset = [], 16
    for _ in range(count):
        if offset + 16 > len(raw):
            raise RuntimeError('native lowering literal header is truncated')
        kind, word = struct.unpack_from('<QQ', raw, offset)
        offset += 16
        if kind == 0:
            if word != 0:
                raise RuntimeError('native lowering None literal differs')
            value = None
        elif kind == 1:
            if word > 1:
                raise RuntimeError('native lowering Boolean literal differs')
            value = bool(word)
        elif kind == 2:
            value = word
        elif kind == 3:
            padded = (word + 7) & -8
            if padded > len(raw) - offset:
                raise RuntimeError('native lowering text literal is truncated')
            value = raw[offset:offset + word].decode('utf-8')
            if any(raw[offset + word:offset + padded]):
                raise RuntimeError('native lowering text padding differs')
            offset += padded
        else:
            raise RuntimeError('native lowering literal kind differs')
        values.append(value)
    if offset != len(raw) or len(values) < 3 or values[:3] != [None, False, True]:
        raise RuntimeError('native lowering literal extent differs')
    if type(values[1]) is not bool or type(values[2]) is not bool:
        raise RuntimeError('native lowering Boolean identities differ')
    # Handle identity is essential for HIA's IS primitive. Repeated pool values
    # are invalid; the authoring pool already deduplicates by exact type/value.
    identities = {id(value) for value in values}
    if len(identities) != len(values):
        raise RuntimeError('native lowering literal handles are not distinct')
    return tuple(values)


class LoweringSession:
    """One private, single-use HIA continuation; handles keep objects alive."""

    def __init__(self, owner, mode, arguments):
        if type(mode) is not int or type(arguments) is not tuple or len(arguments) > 4:
            raise TypeError('exact native lowering invocation frame required')
        self.owner = owner
        self.values = [None, *owner.literals]
        self.handles = {id(value): index for index, value in enumerate(self.values) if index}
        self.state = ctypes.create_string_buffer(owner.workspace_bytes)
        self.output = ctypes.create_string_buffer(owner.output_bytes)
        self.input = ctypes.create_string_buffer(128)
        self.unit = 0
        self.status = None
        self.pending = False
        self.finished = False
        self.request = None
        args = tuple(self.register(value) for value in arguments)
        words = (MAGIC, 0, 0, mode, len(args), *args)
        self.initial = FRAME.pack(*words, *([0] * (16 - len(words))))

    def register(self, value):
        identity = id(value)
        previous = self.handles.get(identity)
        if previous is not None:
            if self.values[previous] is not value:
                raise RuntimeError('native lowering handle identity was reused')
            return previous
        handle = len(self.values)
        if handle >= 1 << 64:
            raise OverflowError('native lowering foreign handle extent exceeded')
        self.values.append(value)
        self.handles[identity] = handle
        return handle

    def value(self, handle):
        if type(handle) is not int or not 0 < handle < len(self.values):
            raise RuntimeError('native lowering requested an unknown object')
        return self.values[handle]

    def _close(self):
        self.finished, self.pending, self.request = True, False, None

    def step(self, packet):
        if self.finished:
            raise RuntimeError('native lowering session is closed')
        if type(packet) is not bytes or len(packet) != 128:
            self._close()
            raise TypeError('exact 128-byte native lowering packet required')
        # Successful one-shot observations consume their permission before they
        # return a packet. Raw ABI controls may submit packets directly; HIA is
        # still responsible for rejecting wrong phases, sequences and counts.
        self.pending = False
        try:
            ctypes.memmove(self.input, packet, 128)
            result = self.owner.images[self.unit]._entry(
                self.input, 128, self.output, len(self.output), self.state, len(self.state))
            if result not in (0, 1, 2):
                raise RuntimeError('native lowering protocol refusal: ' + hex(result))
            header = struct.unpack_from('<16Q', self.output)
            if header[0] != MAGIC:
                raise RuntimeError('native lowering output identity differs')
            if result == 0:
                if header[2] != 0:
                    raise RuntimeError('native lowering return framing differs')
                returned = self.value(header[3])
                self.status, self.returned = 0, returned
                self._close()
                return 0
            if result == 2:
                if header[2] != 19 or header[3] >= len(self.owner.images):
                    raise RuntimeError('native lowering handoff framing differs')
                self.request = header
            else:
                opcode, count, vector_count, results = header[2:6]
                if not 1 <= opcode <= 18 or count > 8 or results > 3:
                    raise RuntimeError('native lowering primitive framing differs')
                if 128 + vector_count * 8 > len(self.output):
                    raise RuntimeError('native lowering vector exceeds private output')
                vector = struct.unpack_from('<' + 'Q' * vector_count, self.output, 128)
                self.request = (header, vector)
            self.status, self.pending = result, True
            return result
        except BaseException:
            self._close()
            raise

    def handoff(self):
        if self.finished or not self.pending or self.status != 2:
            self._close()
            raise RuntimeError('native lowering handoff is not pending')
        self.pending = False
        try:
            header = self.request
            self.unit = header[3]
            return FRAME.pack(MAGIC, 2, header[1], self.unit, *([0] * 12))
        except BaseException:
            self._close()
            raise

    def observe(self):
        if self.finished or not self.pending or self.status != 1:
            self._close()
            raise RuntimeError('native lowering observation is not pending')
        # Consume before attribute access/calls. A failing foreign observation
        # cannot be replayed, including KeyboardInterrupt/SystemExit/MemoryError.
        self.pending = False
        try:
            header, vector = self.request
            opcode, count, nvector, nresults = header[2:6]
            args = header[8:8 + count]
            if opcode != 7 and vector:
                raise RuntimeError('native lowering unexpected primitive vector')
            flag, results = self._primitive(opcode, args, vector)
            if len(results) != nresults or flag not in (0, 1):
                raise RuntimeError('native lowering primitive result shape differs')
            handles = tuple(self.register(value) for value in results)
            words = (MAGIC, 1, header[1], len(handles), flag, *handles)
            return FRAME.pack(*words, *([0] * (16 - len(words))))
        except BaseException:
            self._close()
            raise

    def _primitive(self, opcode, args, vector):
        get = self.value
        if opcode == 1:  # global name selected by HIA
            name, = args
            return 0, (self.owner.global_value(get(name)),)
        if opcode == 2:
            value, name = args
            return 0, (getattr(get(value), get(name)),)
        if opcode == 3:
            value, name, assigned = args
            setattr(get(value), get(name), get(assigned))
            return 0, ()
        if opcode == 4:
            value, key = args
            return 0, (get(value)[get(key)],)
        if opcode == 5:
            value, key, assigned = args
            get(value)[get(key)] = get(assigned)
            return 0, ()
        if opcode == 6:
            callee, argc, a, b, c, d, key, value = args
            if argc > 4:
                raise RuntimeError('native lowering call arity differs')
            target = get(callee)
            positional = tuple(get(v) for v in (a, b, c, d)[:argc])
            keyword = get(key)
            if keyword is None:
                result = target(*positional)
            else:
                result = target(*positional, **{keyword: get(value)})
            return 0, (result,)
        if opcode == 7:
            kind, count = args
            if count != len(vector):
                raise RuntimeError('native lowering collection extent differs')
            values = tuple(get(value) for value in vector)
            if kind == 1:
                result = list(values)
            elif kind == 2:
                result = values
            elif kind == 3:
                result = set(values)
            elif kind == 4:
                if count % 2:
                    raise RuntimeError('native lowering dictionary extent differs')
                result = {}
                for i in range(0, count, 2):
                    result[values[i]] = values[i + 1]
            else:
                raise RuntimeError('native lowering collection kind differs')
            return 0, (result,)
        if vector:
            raise RuntimeError('native lowering unexpected vector')
        if opcode == 8:
            value, = args
            return 0, (iter(get(value)),)
        if opcode == 9:
            value, = args
            try:
                result = next(get(value))
            except StopIteration:
                return 0, (None,)
            return 1, (result,)
        if opcode == 10:
            value, = args
            return int(bool(get(value))), ()
        if opcode == 11:
            operation, left, right = args
            return 0, (_BINARY[operation](get(left), get(right)),)
        if opcode == 12:
            operation, value = args
            return 0, (_UNARY[operation](get(value)),)
        if opcode == 13:
            operation, left, right = args
            return 0, (_COMPARE[operation](get(left), get(right)),)
        if opcode == 14:
            value, count = args
            observed = get(value)
            if count == 1:
                a, = observed
                results = (a,)
            elif count == 2:
                a, b = observed
                results = (a, b)
            elif count == 3:
                a, b, c = observed
                results = (a, b, c)
            else:
                raise RuntimeError('native lowering unpack arity differs')
            return 0, results
        if opcode == 15:
            low, high, step = args
            return 0, (slice(get(low), get(high), get(step)),)
        if opcode == 16:
            value, item = args
            list.append(get(value), get(item))
            return 0, ()
        if opcode == 17:
            if args:
                raise RuntimeError('native lowering import framing differs')
            from hepta.hia_machine_plan import VALUE_REGISTERS
            return 0, (VALUE_REGISTERS,)
        if opcode == 18:
            value, = args
            raise get(value)
        raise RuntimeError('native lowering unknown primitive')

    def run(self):
        packet = self.initial
        while True:
            status = self.step(packet)
            if status == 0:
                return self.returned
            packet = self.handoff() if status == 2 else self.observe()


class NativeCoreLowering:
    """Development composition of admitted images; production loader pending."""

    def __init__(self, images, pool, abi, namespace):
        if type(abi) is not dict or abi.get('schema') != 'hepta.hia.core-lowering-abi.v1':
            raise ValueError('native lowering ABI metadata differs')
        if abi.get('protocol_magic') != MAGIC or abi.get('pool_magic') != POOL_MAGIC or abi.get('packet_bytes') != 128:
            raise ValueError('native lowering protocol identity differs')
        self.images = tuple(images)
        if not self.images or len(self.images) != len(abi['units']):
            raise ValueError('native lowering image inventory differs')
        self.workspace_bytes, self.output_bytes = abi['workspace_bytes'], abi['output_bytes']
        if (type(self.workspace_bytes) is not int or type(self.output_bytes) is not int
                or self.workspace_bytes < 1024 or self.output_bytes < 128):
            raise ValueError('native lowering private extents differ')
        self.modes = abi['modes']
        self.namespace = namespace
        output = ctypes.create_string_buffer(abi['pool_bytes'])
        empty = ctypes.create_string_buffer(1)
        count = pool._entry(empty, 0, output, len(output), empty, 0)
        if count != abi['pool_bytes']:
            raise RuntimeError('native lowering literal image refused')
        self.literals = _decode_pool(ctypes.string_at(output, count), abi['literal_count'])
        self._classes = {}
        # These wrappers bind the original helper signatures; every body is
        # another HIA invocation, never the retained helper implementation.
        def reject(message, code='E_HIA_PROGRAM_NATIVE'):
            return self.invoke('_reject', (message, code))
        def words(typ):
            return self.invoke('_words', (typ,))
        def bounds(typ):
            return self.invoke('_bounds', (typ,))
        def normalize(code, reg, typ):
            return self.invoke('_normalize', (code, reg, typ))
        def prologue(code, frame):
            return self.invoke('_prologue', (code, frame))
        self._helpers = {'_reject': reject, '_words': words, '_bounds': bounds,
                         '_normalize': normalize, '_prologue': prologue}

    def global_value(self, name):
        # Private helper replacement is not a runtime fallback. Remaining module
        # globals are observed at the HIA-selected original lookup point.
        if name in self._helpers:
            return self._helpers[name]
        if name in self.namespace:
            return self.namespace[name]
        try:
            return getattr(builtins, name)
        except AttributeError:
            raise NameError("name '" + name + "' is not defined") from None

    def invoke(self, name, arguments):
        mode = self.modes[name]
        if len(arguments) != mode['arity']:
            raise RuntimeError('native lowering bound argument count differs')
        return LoweringSession(self, mode['number'], arguments).run()

    def function_class(self, base):
        previous = self._classes.get(base)
        if previous is not None:
            return previous
        owner = self

        class Function(base):
            def __init__(self, parent, fn, index):
                owner.invoke('_Function.__init__', (self, parent, fn, index))

            def allocate(self, words):
                return owner.invoke('_Function.allocate', (self, words))

            def label(self, suffix):
                return owner.invoke('_Function.label', (self, suffix))

            def block_label(self, name):
                return owner.invoke('_Function.block_label', (self, name))

            def load(self, name, reg='rax', word=0):
                return owner.invoke('_Function.load', (self, name, reg, word))

            def store(self, name, reg='rax', word=0):
                return owner.invoke('_Function.store', (self, name, reg, word))

            def immediate(self, name, value, word=0):
                return owner.invoke('_Function.immediate', (self, name, value, word))

            def copy(self, source, destination):
                return owner.invoke('_Function.copy', (self, source, destination))

            def fail_if(self, condition):
                return owner.invoke('_Function.fail_if', (self, condition))

            def compare_imm(self, register, value):
                return owner.invoke('_Function.compare_imm', (self, register, value))

            def range_check(self, register, typ, source=None):
                return owner.invoke('_Function.range_check', (self, register, typ, source))

            def narrow_result(self, typ, checked=False):
                return owner.invoke('_Function.narrow_result', (self, typ, checked))

            def condition_value(self, condition):
                return owner.invoke('_Function.condition_value', (self, condition))

            def edge(self, target, arguments):
                return owner.invoke('_Function.edge', (self, target, arguments))

            def operation(self, ins):
                return owner.invoke('_Function.operation', (self, ins))

            def allocate_buffer(self, size, out, trapping):
                return owner.invoke('_Function.allocate_buffer', (self, size, out, trapping))

            def range_guard(self, buffer, offset, size):
                return owner.invoke('_Function.range_guard', (self, buffer, offset, size))

            def bulk(self, op, args):
                return owner.invoke('_Function.bulk', (self, op, args))

            def push_chain(self, args, out):
                return owner.invoke('_Function.push_chain', (self, args, out))

            def pop_chain(self, arg, out):
                return owner.invoke('_Function.pop_chain', (self, arg, out))

            def drop_chain(self, arg):
                return owner.invoke('_Function.drop_chain', (self, arg))

            def render(self):
                return owner.invoke('_Function.render', (self,))

        self._classes[base] = Function
        return Function
